// ─── Pool global: ALL_600 + cards customizados ────────────────────────────────
// Lê customCards do localStorage e combina com o vocabulário base.
// Usado em todo lugar que precisa do pool completo.

function loadCustomCards() {
  try { return Object.values(JSON.parse(localStorage.getItem("koine_custom_cards") || "{}")); }
  catch { return []; }
}

function useAllCards() {
  const [custom, setCustom] = useState(loadCustomCards);
  useEffect(() => {
    function onStorage(e) {
      if (e.key === "koine_custom_cards") setCustom(loadCustomCards());
    }
    window.addEventListener("storage", onStorage);
    const id = setInterval(() => setCustom(loadCustomCards()), 1500);
    return () => { window.removeEventListener("storage", onStorage); clearInterval(id); };
  }, []);
  return useMemo(() => {
    const greeks = new Set(ALL_DICTIONARY.map(c => c.greek));
    return [...ALL_DICTIONARY, ...custom.filter(c => !greeks.has(c.greek))];
  }, [custom]);
}

