// ─── SRS (SM-2 simplificado) ──────────────────────────────────────────────────
// srsData[greek] = { interval, easeFactor, nextReview }
// Compartilhado entre Vocabulário e Listas — qualquer acerto/erro alimenta o mesmo objeto.

function computeSRS(entry, rating) {
  let { interval = 0, easeFactor = 2.5, repetitions = 0 } = entry || {};

  if (rating === "easy") {
    repetitions += 1;
    if      (repetitions === 1) interval = 1;
    else if (repetitions === 2) interval = 6;
    else                         interval = Math.round(interval * easeFactor);
    easeFactor = Math.min(3.0, easeFactor + 0.15);
  } else if (rating === "medium") {
    repetitions += 1;
    if      (repetitions === 1) interval = 1;
    else if (repetitions === 2) interval = 6;
    else                         interval = Math.round(interval * easeFactor);
    // easeFactor não muda no medium
  } else {
    // errou — reinicia
    repetitions = 0;
    interval    = 1;
    easeFactor  = Math.max(1.3, easeFactor - 0.2);
  }

  interval = Math.max(1, interval);
  return { interval, easeFactor, repetitions, nextReview: Date.now() + interval * 86400000 };
}

