function WordEditModal({ theme, t, language, card, override, onSave, onRestore, onClose }) {
  const [glosa, setGlosa] = React.useState(override?.glosses?.[language] ?? card.glosses[language] ?? "");
  const [note,  setNote]  = React.useState(override?.note ?? "");
  const hasOverride = !!(override?.glosses?.[language]);

  const inputStyle = {
    width:"100%", background:"none", border:"1px solid "+theme.border, borderRadius:"12px",
    padding:"10px 14px", color:theme.text, fontSize:"1.0769em", outline:"none",
    fontFamily:"inherit", boxSizing:"border-box",
  };
  const labelStyle = {
    color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.18em",
    textTransform:"uppercase", marginBottom:"6px", display:"block",
  };

  return (
    <div style={{ position:"fixed", inset:0, backgroundColor:"rgba(0,0,0,0.55)", zIndex:200, display:"flex", alignItems:"flex-start", justifyContent:"center", padding:"120px 20px 0" }}
      onClick={(e)=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ backgroundColor:theme.card, borderRadius:"24px", padding:"24px 20px 32px", width:"100%", boxSizing:"border-box", maxHeight:"75vh", overflowY:"auto" }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"20px" }}>
          <div style={{ fontSize:"24px", fontWeight:300 }}>{card.greek}</div>
          <button onClick={onClose} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"20px", lineHeight:1 }}>×</button>
        </div>
        <label style={labelStyle}>{t.editGlosa}</label>
        <AndroidInput style={inputStyle} value={glosa} onChange={e=>setGlosa(e.target.value)}/>
        <label style={{ ...labelStyle, marginTop:"14px" }}>{t.editNote}</label>
        <AndroidInput style={inputStyle} value={note} onChange={e=>setNote(e.target.value)} placeholder="—"/>
        <div style={{ display:"flex", gap:"8px", marginTop:"20px" }}>
          {hasOverride && (
            <button onClick={onRestore}
              style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"14px",
                padding:"12px 0", color:theme.muted, fontSize:"0.9231em", cursor:"pointer" }}>
              {t.restoreWord}
            </button>
          )}
          <button onClick={()=>onSave({ glosses: { ...(override?.glosses ?? {}), [language]: glosa.trim() || card.glosses[language] }, note: note.trim() })}
            style={{ flex:2, backgroundColor:theme.accent, border:"none", borderRadius:"14px",
              padding:"12px 0", color:"#fff", fontSize:"1.0em", cursor:"pointer" }}>
            {t.save}
          </button>
        </div>
      </div>
    </div>
  );
}


// ─── AndroidInput — resolve IME do Samsung WebView ────────────────────────────
function AndroidInput({ value, onChange, style, placeholder, maxLength, type="text", inputMode, autoCapitalize, readOnly, className }) {
  const ref = useRef(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const onInput          = (e) => { onChange && onChange({ target: { value: e.target.value } }); };
    const onCompositionEnd = (e) => { onChange && onChange({ target: { value: e.target.value } }); };
    const onEnter          = (e) => { if (e.key === "Enter") { e.preventDefault(); el.blur(); } };

    const onFocus = () => {
      try {
        const plugin = window.Capacitor?.Plugins?.SamsungImePlugin;
        if (plugin) plugin.restartInput().catch(()=>{});
      } catch {}
    };

    el.addEventListener("input",          onInput);
    el.addEventListener("compositionend", onCompositionEnd);
    el.addEventListener("keydown",        onEnter);
    el.addEventListener("focus",          onFocus);

    return () => {
      el.removeEventListener("input",          onInput);
      el.removeEventListener("compositionend", onCompositionEnd);
      el.removeEventListener("keydown",        onEnter);
      el.removeEventListener("focus",          onFocus);
    };
  }, [onChange]);

  return (
    <input
      ref={ref}
      type={type}
      inputMode={inputMode}
      autoCapitalize={autoCapitalize ?? "sentences"}
      autoComplete="off"
      autoCorrect="off"
      spellCheck={false}
      readOnly={readOnly}
      placeholder={placeholder}
      maxLength={maxLength}
      className={className}
      style={style}
      defaultValue={value || ""}
    />
  );
}

