// ─── WordPicker ───────────────────────────────────────────────────────────────
// Busca inteligente: grego (com ou sem acentos) + tradução + transliteração latina
// Mostra resultados só após 2 caracteres. Limite de 50 resultados.
// Palavras já na lista aparecem com indicador distinto.

// Mapa de transliteração grego → latim (aproximado, para busca sem teclado grego)
const TRANSLIT = {
  α:"a", ά:"a", ἀ:"a", ἁ:"a", ἂ:"a", ἃ:"a", ἄ:"a", ἅ:"a", ἆ:"a", ἇ:"a", ᾀ:"a", ᾁ:"a", ᾂ:"a", ᾃ:"a", ᾄ:"a", ᾅ:"a", ᾆ:"a", ᾇ:"a", ᾰ:"a", ᾱ:"a", ᾲ:"a", ᾳ:"a", ᾴ:"a", ᾶ:"a", ᾷ:"a",
  β:"b", γ:"g", δ:"d",
  ε:"e", έ:"e", ἐ:"e", ἑ:"e", ἒ:"e", ἓ:"e", ἔ:"e", ἕ:"e",
  ζ:"z",
  η:"e", ή:"e", ἠ:"e", ἡ:"e", ἢ:"e", ἣ:"e", ἤ:"e", ἥ:"e", ἦ:"e", ἧ:"e", ᾐ:"e", ᾑ:"e", ᾒ:"e", ᾓ:"e", ᾔ:"e", ᾕ:"e", ᾖ:"e", ᾗ:"e", ῂ:"e", ῃ:"e", ῄ:"e", ῆ:"e", ῇ:"e",
  θ:"th",
  ι:"i", ί:"i", ϊ:"i", ΐ:"i", ἰ:"i", ἱ:"i", ἲ:"i", ἳ:"i", ἴ:"i", ἵ:"i", ἶ:"i", ἷ:"i", ῐ:"i", ῑ:"i", ῒ:"i", ΐ:"i", ῖ:"i", ῗ:"i",
  κ:"k", λ:"l", μ:"m", ν:"n", ξ:"x",
  ο:"o", ό:"o", ὀ:"o", ὁ:"o", ὂ:"o", ὃ:"o", ὄ:"o", ὅ:"o", ὸ:"o", ό:"o",
  π:"p", ρ:"r", ῥ:"r",
  σ:"s", ς:"s", ϲ:"s",
  τ:"t",
  υ:"u", ύ:"u", ϋ:"u", ΰ:"u", ὐ:"u", ὑ:"u", ὒ:"u", ὓ:"u", ὔ:"u", ὕ:"u", ὖ:"u", ὗ:"u", ῠ:"u", ῡ:"u", ῢ:"u", ΰ:"u", ῦ:"u", ῧ:"u",
  φ:"ph", χ:"ch", ψ:"ps",
  ω:"o", ώ:"o", ὠ:"o", ὡ:"o", ὢ:"o", ὣ:"o", ὤ:"o", ὥ:"o", ὦ:"o", ὧ:"o", ᾠ:"o", ᾡ:"o", ᾢ:"o", ᾣ:"o", ᾤ:"o", ᾥ:"o", ᾦ:"o", ᾧ:"o", ῲ:"o", ῳ:"o", ῴ:"o", ῶ:"o", ῷ:"o",
};

// Normaliza string grega: remove acentos/diacríticos, converte para minúsculas
function normalizeGreek(s) {
  return s.toLowerCase().split("").map(c => {
    // Remove combining diacritics (U+0300–U+036F range) após NFD decomposition
    return c;
  }).join("").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

// Transliterapara latim (para busca com teclado não-grego)
function translitGreek(s) {
  return s.toLowerCase().split("").map(c => TRANSLIT[c] ?? c).join("");
}

function WordPicker({ theme, t, language, currentWords, onDone, allCards }) {
  const [search,   setSearch]   = useState("");
  const [selected, setSelected] = useState(new Set(currentWords));
  const inListSet = useMemo(() => new Set(currentWords), [currentWords]);

  const q = search.trim().toLowerCase();
  const qNorm   = normalizeGreek(q);
  const qTransl = q.replace(/[^a-z]/g, ""); // só letras latinas da query

  const results = useMemo(() => {
    if (q.length < 2) return [];

    function score(card) {
      const greek      = card.greek.toLowerCase();
      const greekNorm  = normalizeGreek(card.greek);
      const greekTr    = translitGreek(card.greek);
      const gloss      = Object.values(card.glosses).join(" ").toLowerCase();

      // Prioridade 0: match exato no início (grego com ou sem acento, transliteração, tradução)
      if (greek.startsWith(q))       return 0;
      if (greekNorm.startsWith(qNorm)) return 0;
      if (qTransl && greekTr.startsWith(qTransl)) return 1;
      if (gloss.startsWith(q))       return 1;

      // Prioridade 2: contém em qualquer posição
      if (greek.includes(q))         return 2;
      if (greekNorm.includes(qNorm)) return 2;
      if (qTransl && greekTr.includes(qTransl)) return 3;
      if (gloss.includes(q))         return 3;

      return 99; // não encontrado
    }

    const scored = (allCards || ALL_600)
      .map(c => ({ card:c, s:score(c) }))
      .filter(x => x.s < 99)
      .sort((a, b) => {
        // Primeiro por score (match mais preciso primeiro)
        if (a.s !== b.s) return a.s - b.s;
        // Mesmo score: palavra mais curta primeiro (mais próxima do que foi digitado)
        const lenDiff = a.card.greek.length - b.card.greek.length;
        if (lenDiff !== 0) return lenDiff;
        // Mesmo tamanho: mais frequente primeiro
        return (b.card.occurrences || 0) - (a.card.occurrences || 0);
      });

    return scored.slice(0, 50).map(x => x.card);
  }, [q, language]);

  const toggle = (greek) => setSelected(prev => {
    const n = new Set(prev);
    n.has(greek) ? n.delete(greek) : n.add(greek);
    return n;
  });

  // Novas seleções (não estavam na lista antes)
  const newCount = [...selected].filter(g => !inListSet.has(g)).length;
  const removedCount = [...inListSet].filter(g => !selected.has(g)).length;

  const placeholder = { pt:"grego ou tradução…", en:"greek or translation…", de:"Griechisch oder Übersetzung…", fr:"grec ou traduction…", es:"griego o traducción…" }[language];

  return (
    <div style={{ position:"fixed", inset:0, backgroundColor:theme.bg, zIndex:150, display:"flex", flexDirection:"column", padding:"20px 20px 8px" }}>

      {/* Header */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"14px", flexShrink:0 }}>
        <div style={{ color:theme.muted, fontSize:"10px", letterSpacing:"0.24em", textTransform:"uppercase" }}>{t.selectWords}</div>
        <button onClick={()=>onDone([...selected])}
          style={{ background:"none", border:"none", color:theme.accent, fontSize:"13px", cursor:"pointer", padding:"4px 8px" }}>
          {t.done}{(newCount>0||removedCount>0) ? ` (${newCount>0?"+"+newCount:""}${removedCount>0?"-"+removedCount:""})` : ""}
        </button>
      </div>

      {/* Campo de busca */}
      <AndroidInput
        value={search}
        onChange={e=>setSearch(e.target.value)}
        placeholder={placeholder}
        autoCapitalize="none"
        style={{ width:"100%", background:theme.soft, border:"1px solid "+theme.border, borderRadius:"14px",
          padding:"10px 14px", fontSize:"14px", color:theme.text, outline:"none",
          marginBottom:"10px", flexShrink:0, boxSizing:"border-box" }}
      />

      {/* Estado vazio / dica */}
      {q.length < 2 && (
        <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:"8px" }}>
          <div style={{ color:theme.muted, fontSize:"13px" }}>
            {{ pt:"Digite pelo menos 2 caracteres", en:"Type at least 2 characters", de:"Mindestens 2 Zeichen eingeben", fr:"Tapez au moins 2 caractères", es:"Escribe al menos 2 caracteres" }[language]}
          </div>
          <div style={{ color:theme.muted, fontSize:"11px", opacity:0.6 }}>
            {{ pt:"grego, transliteração ou tradução", en:"greek, transliteration or translation", de:"Griechisch, Transliteration oder Übersetzung", fr:"grec, translitération ou traduction", es:"griego, transliteración o traducción" }[language]}
          </div>
        </div>
      )}

      {/* Sem resultados */}
      {q.length >= 2 && results.length === 0 && (
        <div style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center" }}>
          <div style={{ color:theme.muted, fontSize:"13px" }}>—</div>
        </div>
      )}

      {/* Lista de resultados */}
      {results.length > 0 && (
        <div style={{ flex:1, overflowY:"auto", paddingBottom:"12px" }}>
          <div style={{ display:"flex", flexDirection:"column", gap:"6px" }}>
            {results.map(card => {
              const sel     = selected.has(card.greek);
              const already = inListSet.has(card.greek);
              const isNew   = sel && !already;
              const borderColor = sel ? theme.accent : theme.border;
              return (
                <button key={card.greek} onClick={()=>toggle(card.greek)}
                  style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
                    padding:"12px 16px", background:"none",
                    border:"1px solid "+borderColor,
                    borderRadius:"16px", cursor:"pointer", textAlign:"left", width:"100%",
                    transition:"border-color 0.15s", opacity: 1 }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"baseline", gap:"8px" }}>
                      <span style={{ fontSize:"20px", fontWeight:300, lineHeight:1.2, color:theme.text }}>{card.greek}</span>
                      <span style={{ fontSize:"9px", color:theme.muted, letterSpacing:"0.12em", textTransform:"uppercase", opacity:0.7 }}>
                        {card.cat}{card.occurrences ? " · "+card.occurrences : ""}
                      </span>
                    </div>
                    <div style={{ fontSize:"11px", color:theme.muted, marginTop:"2px", fontStyle:"italic" }}>{card.glosses[language]}</div>
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:"6px", flexShrink:0, marginLeft:"10px" }}>
                    {already && !sel && (
                      <div style={{ width:"6px", height:"6px", borderRadius:"50%", backgroundColor:theme.muted, opacity:0.4 }} title="já na lista"/>
                    )}
                    <div style={{ width:"20px", height:"20px", borderRadius:"50%",
                      border:"1px solid "+(sel?theme.accent:theme.border),
                      backgroundColor:sel?theme.accent:"transparent",
                      display:"flex", alignItems:"center", justifyContent:"center",
                      transition:"all 0.15s" }}>
                      {sel && <svg width="10" height="10" viewBox="0 0 12 12" fill="none">
                        <polyline points="2,6 5,9 10,3" stroke={theme.bg} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
                      </svg>}
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
          {results.length === 50 && (
            <div style={{ color:theme.muted, fontSize:"10px", textAlign:"center", marginTop:"10px", opacity:0.6 }}>
              {{ pt:"Mostrando 50 resultados — refine a busca", en:"Showing 50 results — refine your search", de:"50 Ergebnisse — Suche verfeinern", fr:"50 résultats — affinez la recherche", es:"50 resultados — refine la búsqueda" }[language]}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ─── QuizScreen — quiz adaptativo com SRS, requeue e distractores inteligentes ─
//
// Lógica:
//  • Distractores inteligentes: escolhemos palavras com ocorrências próximas (mesma faixa de freq.)
//  • Requeue: palavras erradas voltam ao final da fila — você precisa acertar cada uma ao menos 1x
//  • "Domínio" por palavra: só sai da fila quando acerta sem ter errado antes nessa rodada
//  • SRS: acerto → intervalo duplica; erro → reseta para 1 dia (SM-2 simplificado)
//  • Lista de erradas: salva automaticamente no localStorage para revisão posterior
//  • Progresso: barra mostra palavras *dominadas* / total único

function QuizScreen({ theme, t, language, cards, onClose, onSRS, onWrongWords, onQuizResults, allCards }) {

  // ── distractores inteligentes ──────────────────────────────────────────────
  function smartDistractors(card) {
    // Prefer words with similar occurrence count (same frequency band)
    const freq = card.occurrences;
    const pool = (allCards || ALL_600).filter(c => c.greek !== card.greek);
    // Sort by proximity in frequency, with slight shuffle to avoid always same distractors
    const sorted = [...pool].sort((a, b) => {
      const da = Math.abs(a.occurrences - freq);
      const db = Math.abs(b.occurrences - freq);
      return da - db + (Math.random() - 0.5) * 200;
    });
    return sorted.slice(0, 3).map(c => c.glosses[language]);
  }

  function makeOpts(card) {
    if (!card) return [];
    return shuffle([...smartDistractors(card), card.glosses[language]]);
  }

  // ── estado da fila ─────────────────────────────────────────────────────────
  const initialQueue = useMemo(() => shuffle(cards).map(c => ({ card:c })), []);
  const [queue,     setQueue]     = useState(initialQueue);
  const [qIdx,      setQIdx]      = useState(0);
  const [dominated, setDominated] = useState(new Set());
  const [score,     setScore]     = useState({ correct:0, wrong:0 });
  const [done,      setDone]      = useState(false);

  // UI de resposta
  const [options,      setOpts]      = useState(() => makeOpts(initialQueue[0]?.card));
  const [chosen,       setChosen]    = useState(null);
  const [flashPhase,   setFlashPhase]= useState(null); // null | 'wrong'

  // palavras erradas nessa sessão
  const [wrongSet, setWrongSet] = useState(new Set());

  // ── cronômetro por pergunta ────────────────────────────────────────────────
  const questionStartRef = useRef(Date.now());
  const timingResultsRef = useRef({});
  const onQuizResultsRef = useRef(onQuizResults);
  useEffect(() => { onQuizResultsRef.current = onQuizResults; }, [onQuizResults]);

  const totalUnique = cards.length;
  const dominatedCount = dominated.size;

  // ── avançar na fila ────────────────────────────────────────────────────────
  function advance(nextIdx, nextQueue) {
    const q = nextQueue ?? queue;
    if (nextIdx >= q.length) {
      // sessão encerrada — salvar erradas
      if (wrongSet.size > 0 && onWrongWords) {
        onWrongWords([...wrongSet]);
      }
      // disparar resultados de tempo diretamente (síncrono — evita problema de desmontagem)
      if (onQuizResultsRef.current && Object.keys(timingResultsRef.current).length > 0) {
        onQuizResultsRef.current({ ...timingResultsRef.current });
      }
      setDone(true);
      return;
    }
    setQIdx(nextIdx);
    setChosen(null);
    setFlashPhase(null);
    setOpts(makeOpts(q[nextIdx].card));
    questionStartRef.current = Date.now();
  }

  // ── resposta ───────────────────────────────────────────────────────────────
  function answer(opt) {
    if (chosen || flashPhase) return;
    const current = queue[qIdx];
    const card    = current.card;
    const ok      = opt === card.glosses[language];
    const elapsed = (Date.now() - questionStartRef.current) / 1000; // segundos

    setChosen(opt);

    if (ok) {
      setScore(s => ({ ...s, correct: s.correct + 1 }));
      onSRS(card.greek, "easy");
      timingResultsRef.current[card.greek] = { time: elapsed, wrong: false };
      setDominated(prev => new Set([...prev, card.greek]));

      setTimeout(() => {
        setQueue(q => {
          const next = [...q.slice(0, qIdx), ...q.slice(qIdx + 1)];
          advance(qIdx < next.length ? qIdx : 0, next);
          return next;
        });
      }, 600);

    } else {
      // Erro — mostra feedback 1s e avança (sem requeue)
      setScore(s => ({ ...s, wrong: s.wrong + 1 }));
      onSRS(card.greek, "hard");
      setWrongSet(prev => new Set([...prev, card.greek]));
      timingResultsRef.current[card.greek] = { time: elapsed, wrong: true };
      setFlashPhase('wrong');

      setTimeout(() => {
        setFlashPhase(null);
        setQueue(q => {
          const next = [...q.slice(0, qIdx), ...q.slice(qIdx + 1)];
          advance(qIdx < next.length ? qIdx : 0, next);
          return next;
        });
      }, 1200);
    }
  }

  // Cronômetro ao vivo — DEVE ficar antes de qualquer return condicional (Rules of Hooks)
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (done) return;
    questionStartRef.current = Date.now();
    setElapsed(0);
    const iv = setInterval(() => setElapsed(Math.floor((Date.now() - questionStartRef.current) / 1000)), 200);
    return () => clearInterval(iv);
  }, [qIdx, done]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── tela de resultado ──────────────────────────────────────────────────────
  if (done) {
    const total   = score.correct + score.wrong;
    const pct     = total > 0 ? Math.round((score.correct / total) * 100) : 100;
    const msg     = pct === 100 ? t.perfect : pct >= 70 ? t.wellDone : t.keepGoing;
    const wrongArr = [...wrongSet];

    function restart() {
      const q = shuffle(cards).map(c => ({ card:c }));
      setQueue(q);
      setQIdx(0);
      setDominated(new Set());
      setScore({ correct:0, wrong:0 });
      setDone(false);
      setWrongSet(new Set());
      setChosen(null);
      setFlashPhase(null);
      timingResultsRef.current = {};
      setOpts(makeOpts(q[0]?.card));
      questionStartRef.current = Date.now();
    }

    function restartWrong() {
      if (!wrongArr.length) return;
      const wrongCards = wrongArr.map(g => allCards.find(c => c.greek === g)).filter(Boolean);
      const q = shuffle(wrongCards).map(c => ({ card:c }));
      setQueue(q);
      setQIdx(0);
      setDominated(new Set());
      setScore({ correct:0, wrong:0 });
      setDone(false);
      setWrongSet(new Set());
      setChosen(null);
      setFlashPhase(null);
      timingResultsRef.current = {};
      setOpts(makeOpts(q[0]?.card));
      questionStartRef.current = Date.now();
    }

    return (
      <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:"20px", padding:"0 4px" }}>
        <div style={{ fontSize:"22px", fontWeight:300 }}>{msg}</div>

        {/* Placar */}
        <div style={{ backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"24px", padding:"24px", width:"100%", display:"flex", flexDirection:"column", alignItems:"center", gap:"16px" }}>
          <div style={{ fontSize:"40px", fontWeight:300 }}>{pct}%</div>
          <div style={{ display:"flex", gap:"32px" }}>
            <div style={{ textAlign:"center" }}>
              <div style={{ color:"#6BA86A", fontSize:"28px", fontWeight:300 }}>{score.correct}</div>
              <div style={{ color:theme.muted, fontSize:"10px", textTransform:"uppercase", letterSpacing:"0.1em" }}>{t.correct}</div>
            </div>
            <div style={{ color:theme.border, fontSize:"28px" }}>·</div>
            <div style={{ textAlign:"center" }}>
              <div style={{ color:"#C0706A", fontSize:"28px", fontWeight:300 }}>{score.wrong}</div>
              <div style={{ color:theme.muted, fontSize:"10px", textTransform:"uppercase", letterSpacing:"0.1em" }}>{t.wrong}</div>
            </div>
          </div>
          <div style={{ backgroundColor:theme.border, borderRadius:"9999px", height:"4px", width:"100%" }}>
            <div style={{ backgroundColor:"#6BA86A", width:pct+"%", height:"4px", borderRadius:"9999px", transition:"width 0.6s ease" }}/>
          </div>
        </div>

        {/* Botões */}
        <div style={{ display:"flex", gap:"8px", width:"100%" }}>
          <button onClick={restart}
            style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"12px 0", color:theme.accent, fontSize:"13px", cursor:"pointer" }}>{t.repeat}</button>
          <button onClick={onClose}
            style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"12px 0", color:theme.muted, fontSize:"13px", cursor:"pointer" }}>{t.back}</button>
        </div>
      </div>
    );
  }

  // ── tela de pergunta ───────────────────────────────────────────────────────
  if (!queue[qIdx]) return null;
  const card        = queue[qIdx].card;
  const progressPct = totalUnique > 0 ? Math.round((dominatedCount / totalUnique) * 100) : 0;
  const remaining   = queue.length;
  const timerColor  = elapsed <= 6 ? "#6BA86A" : "#C0706A";

  return (
    <div style={{ flex:1, display:"flex", flexDirection:"column", fontSize:"13px" }}>

      {/* Header */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"12px", paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
        <button onClick={onClose} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"13px" }}>← {t.back}</button>
        <div style={{ display:"flex", alignItems:"center", gap:"12px" }}>
          <span style={{ color:"#6BA86A", fontSize:"12px" }}>✓ {dominatedCount}/{totalUnique}</span>
          <span style={{ color:timerColor, fontSize:"13px", fontVariantNumeric:"tabular-nums", minWidth:"24px", textAlign:"center", transition:"color 0.3s" }}>
            {elapsed}s
          </span>
          <span style={{ color:theme.muted, fontSize:"10px" }}>{{pt:`${remaining} restantes`, en:`${remaining} left`, de:`${remaining} übrig`, fr:`${remaining} restants`, es:`${remaining} restantes`}[language]}</span>
          <span style={{ color:"#C0706A", fontSize:"12px" }}>✗ {score.wrong}</span>
        </div>
      </div>

      {/* Barra de progresso */}
      <div style={{ backgroundColor:theme.border, borderRadius:"9999px", height:"3px", marginBottom:"20px" }}>
        <div style={{ backgroundColor:theme.accent, width:progressPct+"%", height:"3px", borderRadius:"9999px", transition:"width 0.5s ease" }}/>
      </div>

      {/* Card da palavra */}
      <div style={{ position:"relative", backgroundColor:theme.card, border:"1px solid "+theme.border,
        borderRadius:"24px", padding:"28px 20px", display:"flex", flexDirection:"column", alignItems:"center",
        justifyContent:"center", minHeight:"140px", marginBottom:"20px", textAlign:"center", flexShrink:0 }}>
        {catLabel(card, language) && (
          <div style={{ position:"absolute", top:"10px", left:"14px", color:theme.muted, fontSize:"9px", letterSpacing:"0.12em", textTransform:"uppercase", opacity:0.55 }}>
            {catLabel(card, language)}
          </div>
        )}
        {genderLabel(card, language) && (
          <div style={{ position:"absolute", top:"10px", right:"14px", color:theme.muted, fontSize:"9px", letterSpacing:"0.12em", textTransform:"uppercase", opacity:0.55 }}>
            {genderLabel(card, language)}
          </div>
        )}
        <div style={{ fontSize:"39px", fontWeight:300, lineHeight:1, marginBottom:"4px" }}>{card.greek}</div>
        {card.occurrences > 0 && (
          <div style={{ position:"absolute", bottom:"10px", left:"14px", color:theme.muted, fontSize:"9px", opacity:0.55 }}>{card.occurrences}</div>
        )}
      </div>

      {/* Opções */}
      <div style={{ display:"flex", flexDirection:"column", gap:"8px", flex:1 }}>
        {options.map(opt => {
          const isCorrect     = opt === card.glosses[language];
          const isChosen      = opt === chosen;
          const isWrongChosen = isChosen && !isCorrect;
          const showFeedback  = !!chosen;

          let borderColor = theme.border, color = theme.text, bg = theme.soft;
          if (showFeedback) {
            if (isCorrect) {
              borderColor = "#3A6B3A"; color = "#6BA86A"; bg = "rgba(58,107,58,0.13)";
            } else if (isWrongChosen) {
              borderColor = "#8B3A3A"; color = "#C0706A"; bg = "rgba(139,58,58,0.13)";
            }
          }

          return (
            <button key={opt} onClick={() => answer(opt)}
              style={{ background:bg, border:"1px solid "+borderColor, borderRadius:"16px", padding:"12px 16px",
                textAlign:"left", color, fontSize:"13px", cursor:(chosen||flashPhase)?"default":"pointer", width:"100%" }}>
              {opt}
            </button>
          );
        })}
      </div>
    </div>
  );
}

