// ─── ProgressTab ──────────────────────────────────────────────────────────────

function ProgressTab({ theme, t, language, learnedCards, streak, dueCount, onStartReview, quizResults, onReviewGroup, onOpenSettings, allCards }) {
  const [openGroup, setOpenGroup] = useState(null); // null | "consolidated" | "medium" | "wrong"

  // Categorizar palavras pelos resultados acumulados
  const consolidated = Object.entries(quizResults||{}).filter(([,v]) => !v.wrong && v.time <= 6).map(([g]) => g);
  const medium       = Object.entries(quizResults||{}).filter(([,v]) => !v.wrong && v.time > 6).map(([g]) => g);
  const wrong        = Object.entries(quizResults||{}).filter(([,v]) => v.wrong).map(([g]) => g);
  const hasResults   = consolidated.length + medium.length + wrong.length > 0;

  const groups = [
    { key:"consolidated",
      label:{ pt:"Consolidadas", en:"Consolidated", de:"Gefestigt", fr:"Consolidées", es:"Consolidadas" }[language],
      sub:{ pt:"acertadas em ≤6s", en:"correct in ≤6s", de:"richtig in ≤6s", fr:"correctes en ≤6s", es:"correctas en ≤6s" }[language],
      emoji:"🟢", words:consolidated, dot:"#6BA86A", border:"#3A6B3A", bg:"rgba(107,168,106,0.10)" },
    { key:"medium",
      label:{ pt:"Em desenvolvimento", en:"In progress", de:"In Bearbeitung", fr:"En cours", es:"En progreso" }[language],
      sub:{ pt:"acertadas em >6s", en:"correct in >6s", de:"richtig in >6s", fr:"correctes en >6s", es:"correctas en >6s" }[language],
      emoji:"🟡", words:medium, dot:"#D4A853", border:"#8B6914", bg:"rgba(212,168,83,0.10)" },
    { key:"wrong",
      label:{ pt:"Erradas", en:"Wrong", de:"Falsch", fr:"Erreurs", es:"Errores" }[language],
      sub:{ pt:"respondidas errado", en:"answered wrong", de:"falsch beantwortet", fr:"réponses incorrectes", es:"respondidas mal" }[language],
      emoji:"🔴", words:wrong, dot:"#C0706A", border:"#8B3A3A", bg:"rgba(192,112,106,0.10)" },
  ];

  // ── Tela de detalhe de um grupo ───────────────────────────────────────────
  if (openGroup) {
    const g = groups.find(x => x.key === openGroup);
    const customCards = Object.values(JSON.parse(localStorage.getItem("koine_custom_cards") || "{}"));
    const allCardsWithCustom = [...(allCards || []), ...customCards];
    const groupCards = g.words
      .map(greek => allCardsWithCustom.find(c => c.greek === greek || c.greek.normalize() === greek.normalize()))
      .filter(Boolean);
    return (
      <div style={{ flex:1, display:"flex", flexDirection:"column" }}>
        {/* Header */}
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"20px", flexShrink:0 }}>
          <button onClick={()=>setOpenGroup(null)} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em" }}>← {t.back}</button>
          <div style={{ display:"flex", alignItems:"center", gap:"6px" }}>
            <div style={{ width:"8px", height:"8px", borderRadius:"50%", backgroundColor:g.dot }}/>
            <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase" }}>{g.label}</div>
          </div>
          <div style={{ width:36 }}/>
        </div>

        {/* Botões de revisão */}
        {groupCards.length > 0 && (
          <div style={{ display:"flex", gap:"8px", marginBottom:"16px", flexShrink:0 }}>
            <button onClick={()=>onReviewGroup("flash", g.words)}
              style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"13px 0",
                color:theme.text, fontSize:"1.0em", cursor:"pointer" }}>
              Flashcards
            </button>
            <button onClick={()=>{ if(groupCards.length >= 2) onReviewGroup("quiz", g.words); }}
              style={{ flex:1, background:"none", border:"1px solid "+(groupCards.length>=2?theme.border:theme.soft), borderRadius:"16px", padding:"13px 0",
                color:groupCards.length>=2?theme.text:theme.muted, fontSize:"1.0em", cursor:groupCards.length>=2?"pointer":"not-allowed" }}>
              {t.quiz}
            </button>
          </div>
        )}

        {/* Lista de palavras */}
        <div style={{ flex:1, overflowY:"auto", display:"flex", flexDirection:"column", gap:"6px", paddingBottom:"12px", fontSize:"13px" }}>
          {groupCards.length === 0 ? (
            <div style={{ color:theme.muted, fontSize:"13px", textAlign:"center", paddingTop:"40px" }}>—</div>
          ) : groupCards.map(card => (
            <div key={card.greek} style={{ backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"16px", padding:"12px 16px",
              display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              <div>
                <div style={{ fontSize:"22px", fontWeight:300, lineHeight:1.2 }}>{card.greek}</div>
                <div style={{ color:theme.muted, fontSize:"11px", fontStyle:"italic", marginTop:"2px" }}>{card.glosses[language]}</div>
              </div>
              {quizResults[card.greek] && (
                <div style={{ color:g.dot, fontSize:"11px", fontVariantNumeric:"tabular-nums", flexShrink:0, marginLeft:"12px" }}>
                  {quizResults[card.greek].wrong
                    ? ({pt:"errada", en:"wrong", de:"falsch", fr:"erreur", es:"errada" })[language]
                    : `${quizResults[card.greek].time.toFixed(1)}s`}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    );
  }

  // ── Tela principal do Progresso ────────────────────────────────────────────
  return (
    <div style={{ flex:1, display:"flex", flexDirection:"column", gap:"12px", overflowY:"auto", paddingBottom:"8px" }}>

      {/* Cabeçalho */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", flexShrink:0 }}>
        <div>
          <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.25em", textTransform:"uppercase" }}>Koine</div>
          <div style={{ color:theme.muted, fontSize:"0.9231em", marginTop:"2px" }}>{t.progress}</div>
        </div>
        <button onClick={onOpenSettings}
          style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", padding:"4px", display:"flex", alignItems:"center" }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="3"/>
            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>
          </svg>
        </button>
      </div>

      {/* ── Card: Nível de Domínio ── */}
      {(() => {
        const TOTAL_WORDS = ALL_600.length;
        const consolidated600 = consolidated.filter(g => ALL_600.some(c => c.greek === g));
        const MASTERY_LEVELS = [
          { min:0,   max:99,  label:{ pt:"Familiaridade", en:"Familiarity", de:"Vertrautheit", fr:"Familiarité", es:"Familiaridad" },
            desc:{ pt:"Vocabulário de altíssima frequência", en:"Highest-frequency vocabulary", de:"Höchstfrequentes Vokabular", fr:"Vocabulaire à très haute fréquence", es:"Vocabulario de altísima frecuencia" } },
          { min:100, max:199, label:{ pt:"Reconhecimento", en:"Recognition", de:"Erkennung", fr:"Reconnaissance", es:"Reconocimiento" },
            desc:{ pt:"Vocabulário de frequência média-alta", en:"Medium-high frequency vocabulary", de:"Mittel-hohes Vokabular", fr:"Vocabulaire moyen-élevé", es:"Vocabulario de frecuencia media-alta" } },
          { min:200, max:299, label:{ pt:"Leitura", en:"Reading", de:"Lesen", fr:"Lecture", es:"Lectura" },
            desc:{ pt:"Vocabulário de frequência média", en:"Medium frequency vocabulary", de:"Mittleres Vokabular", fr:"Vocabulaire de fréquence moyenne", es:"Vocabulario de frecuencia media" } },
          { min:300, max:399, label:{ pt:"Profundidade", en:"Depth", de:"Tiefe", fr:"Profondeur", es:"Profundidad" },
            desc:{ pt:"Vocabulário especializado do NT", en:"Specialized NT vocabulary", de:"Spezialisiertes NT-Vokabular", fr:"Vocabulaire spécialisé du NT", es:"Vocabulario especializado del NT" } },
          { min:400, max:500, label:{ pt:"Imersão", en:"Immersion", de:"Immersion", fr:"Immersion", es:"Inmersión" },
            desc:{ pt:"Domínio pleno do vocabulário do NT", en:"Full mastery of NT vocabulary", de:"Vollständige Beherrschung des NT-Vokabulars", fr:"Maîtrise complète du vocabulaire du NT", es:"Dominio pleno del vocabulario del NT" } },
        ];
        const LAST_IDX = MASTERY_LEVELS.length - 1;
        const n = consolidated600.length;
        const pct = Math.min(100, Math.round((n / TOTAL_WORDS) * 100));
        const lvlIdx = MASTERY_LEVELS.findIndex(l => n >= l.min && n <= l.max);
        const lvl = MASTERY_LEVELS[Math.max(0, lvlIdx)];
        const nextLvl = MASTERY_LEVELS[Math.min(LAST_IDX, lvlIdx + 1)];
        const lvlNum = lvlIdx + 1;
        const wordsToNext = lvlIdx < LAST_IDX ? nextLvl.min - n : 0;
        return (
          <div style={{ backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"24px", padding:"20px", flexShrink:0 }}>
            <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", marginBottom:"16px" }}>
              <div>
                <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"4px" }}>
                  {{ pt:"Domínio", en:"Mastery", de:"Beherrschung", fr:"Maîtrise", es:"Dominio" }[language]}
                </div>
                <div style={{ fontSize:"1.6923em", fontWeight:300, lineHeight:1.1 }}>{lvl.label[language]}</div>
              </div>
              <div style={{ textAlign:"right", flexShrink:0, marginLeft:"12px" }}>
                <div style={{ fontSize:"2.4615em", fontWeight:300, lineHeight:1, color:theme.accent }}>{pct}%</div>
                <div style={{ color:theme.muted, fontSize:"0.6923em", letterSpacing:"0.1em", textTransform:"uppercase", marginTop:"2px" }}>
                  {{ pt:`Nível ${lvlNum}`, en:`Level ${lvlNum}`, de:`Stufe ${lvlNum}`, fr:`Niveau ${lvlNum}`, es:`Nivel ${lvlNum}` }[language]}
                </div>
              </div>
            </div>
            {/* Barra de progresso */}
            <div style={{ backgroundColor:theme.border, borderRadius:"9999px", height:"4px", marginBottom:"10px" }}>
              <div style={{ backgroundColor:theme.accent, width:pct+"%", height:"4px", borderRadius:"9999px", transition:"width 0.7s ease" }}/>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <div style={{ color:theme.muted, fontSize:"0.8462em" }}>
                <span style={{ color:theme.text }}>{n}</span> / {TOTAL_WORDS} {{ pt:"consolidadas", en:"consolidated", de:"gefestigt", fr:"consolidées", es:"consolidadas" }[language]}
              </div>
              {lvlIdx < LAST_IDX && (
                <div style={{ color:theme.muted, fontSize:"0.7692em" }}>
                  +{wordsToNext} → <span style={{ color:theme.muted, fontStyle:"italic" }}>{nextLvl.label[language]}</span>
                </div>
              )}
            </div>
          </div>
        );
      })()}

      {/* ── Card: Resultados do Quiz ── */}
      <div style={{ backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"24px", padding:"20px", flexShrink:0 }}>
        <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"16px" }}>
          {{ pt:"Resultados", en:"Results", de:"Ergebnisse", fr:"Résultats", es:"Resultados" }[language]}
        </div>

        {!hasResults ? (
          <div style={{ textAlign:"center", paddingTop:"4px", paddingBottom:"4px" }}>
            <div style={{ color:theme.muted, fontSize:"1.0em", marginBottom:"4px" }}>{t.noQuizResults}</div>
            <div style={{ color:theme.muted, fontSize:"0.8462em", opacity:0.55 }}>{t.noQuizHint}</div>
          </div>
        ) : (
          <div style={{ display:"flex", flexDirection:"column", gap:"8px" }}>
            {groups.map((g, i) => (
              <button key={g.key} onClick={()=>setOpenGroup(g.key)}
                style={{ display:"flex", alignItems:"center", background:g.bg,
                  border:"1px solid "+g.border+"44", borderRadius:"16px",
                  padding:"12px 14px", cursor:"pointer", textAlign:"left", width:"100%",
                  gap:"12px" }}>
                {/* Indicador colorido */}
                <div style={{ width:"4px", borderRadius:"4px", alignSelf:"stretch", backgroundColor:g.dot, flexShrink:0 }}/>
                {/* Texto */}
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ color:g.dot, fontSize:"0.9231em", fontWeight:400, letterSpacing:"0.02em" }}>{g.label}</div>
                </div>
                {/* Contagem */}
                <div style={{ color:g.dot, fontSize:"2.0em", fontWeight:300, lineHeight:1, flexShrink:0 }}>{g.words.length}</div>
                {/* Seta */}
                <div style={{ color:theme.muted, fontSize:"0.9231em", flexShrink:0, opacity:0.6 }}>›</div>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* ── Sequência + Revisão pendente ── */}
      <div style={{ display:"flex", gap:"10px", flexShrink:0 }}>
        <div style={{ flex:1, backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"20px", padding:"18px 20px" }}>
          <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"6px" }}>{t.streak}</div>
          <div style={{ fontSize:"2.7692em", fontWeight:300, lineHeight:1, marginBottom:"2px", color:theme.text }}>{streak}</div>
          <div style={{ color:theme.muted, fontSize:"0.8462em" }}>{t.days}</div>
        </div>

        <div onClick={dueCount > 0 ? onStartReview : undefined}
          style={{ flex:1, backgroundColor:theme.card, border:"1px solid "+theme.border,
            borderRadius:"20px", padding:"18px 20px",
            cursor: dueCount > 0 ? "pointer" : "default" }}>
          <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"6px" }}>{t.review}</div>
          <div style={{ fontSize:"2.7692em", fontWeight:300, lineHeight:1, marginBottom:"2px", color: dueCount > 0 ? theme.accent : theme.text }}>{dueCount}</div>
          <div style={{ color:theme.muted, fontSize:"0.8462em" }}>{t.wordsToReview}</div>
        </div>
      </div>

    </div>
  );
}

// ─── ListFlashCards ───────────────────────────────────────────────────────────
// Modo flashcard flip com versículo + SRS — exclusivo das Listas

function ListFlashCards({ theme, t, language, cards, onClose, onSRS, overrides, onSaveOverride, showVerses=true }) {
  const [idx,       setIdx]      = useState(0);
  const [flipped,   setFlipped]  = useState(false);
  const [editCard,  setEditCard]  = useState(null);

  if (!cards.length) return null;

  const card    = cards[idx];
  const total   = cards.length;
  const isLast  = idx === total - 1;
  const ov      = overrides?.[card.greek];
  const displayGlosa = ov?.glosses?.[language] ?? card.glosses[language];

  function goNext() { setIdx(i => (i + 1) % total); setFlipped(false); }
  function goPrev() { setIdx(i => (i - 1 + total) % total); setFlipped(false); }

  function handleSRS(rating) {
    onSRS(card.greek, rating);
    if (!isLast) { goNext(); } else { onClose(); }
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", height:"100%", fontSize:"13px" }}>
      {/* Header */}
      {editCard && (
        <WordEditModal
          theme={theme} t={t} language={language} card={editCard}
          override={overrides?.[editCard.greek]}
          onSave={(ov)=>{ onSaveOverride?.(editCard.greek, ov); setEditCard(null); }}
          onRestore={()=>{ const cur = overrides?.[editCard.greek]; if(cur){ const g={...cur.glosses}; delete g[language]; Object.keys(g).length||!cur.note ? onSaveOverride?.(editCard.greek, Object.keys(g).length?{...cur,glosses:g}:null) : onSaveOverride?.(editCard.greek,{...cur,glosses:g}); } setEditCard(null); }}
          onClose={()=>setEditCard(null)}
        />
      )}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"16px", flexShrink:0 }}>
        <button onClick={onClose} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"13px" }}>← {t.back}</button>
        <div style={{ color:theme.muted, fontSize:"10px", letterSpacing:"0.22em", textTransform:"uppercase" }}>{idx + 1}/{total}</div>
        <button onClick={()=>setEditCard(card)}
          style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", padding:"4px", display:"flex", alignItems:"center" }}
          title={t.editWord}>
          <PencilIcon size={14} color={ov?.glosses?.[language] ? theme.accent : theme.muted}/>
        </button>
      </div>

      {/* Flip card */}
      <FlipCard
        flipped={flipped}
        onFlip={() => setFlipped(f => !f)}
        theme={theme}
        front={
          <div style={{ position:"relative", width:"100%", height:"130px", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
            {catLabel(card, language) && <div style={{ position:"absolute", top:0, left:0, color:theme.muted, fontSize:"9px", letterSpacing:"0.12em", textTransform:"uppercase", opacity:0.55 }}>{catLabel(card, language)}</div>}
            {genderLabel(card, language) && <div style={{ position:"absolute", top:0, right:0, color:theme.muted, fontSize:"9px", letterSpacing:"0.12em", textTransform:"uppercase", opacity:0.55 }}>{genderLabel(card, language)}</div>}
            <div style={{ fontSize:"39px", fontWeight:300, lineHeight:1, marginBottom:"8px" }}>{card.greek}</div>
            <div style={{ color:theme.muted, fontSize:"9px", position:"absolute", bottom:0, left:0, opacity:0.55 }}>{card.occurrences}</div>
          </div>
        }
        back={
          <div style={{ width:"100%", height:"130px", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"0 12px", position:"relative", overflow:"hidden", flexShrink:0 }}>
            <div style={{ fontSize:"22px", fontWeight:300, lineHeight:1.5, textAlign:"center", wordBreak:"break-word" }}>{displayGlosa}</div>
            {ov?.note && <div style={{ color:theme.muted, fontSize:"11px", marginTop:"8px", fontStyle:"italic" }}>{ov.note}</div>}
            {card.note && !ov?.note && (
              <div style={{ position:"absolute", bottom:"8px", right:"12px", color:theme.muted, fontSize:"10px", fontStyle:"italic", opacity:0.7, maxWidth:"60%", textAlign:"right", lineHeight:1.3 }}>
                {card.note}
              </div>
            )}
          </div>
        }
      />

      {/* Versículo */}
      <div style={{ marginTop:16, height: showVerses ? "auto" : 0, minHeight: showVerses ? 80 : 0, display:"flex", flexDirection:"column", justifyContent:"flex-start", flexShrink:0 }}>
        {showVerses && <>
          <div style={{ fontSize:"12px", lineHeight:1.6, fontWeight:300, textAlign:"center", marginBottom:4 }}>{card.verse}</div>
          <div style={{ color:theme.muted, fontSize:"10px", letterSpacing:"0.1em", textAlign:"center" }}>{fmtRef(card.reference)}</div>
        </>}
      </div>

      <div style={{ flex:1 }}/>

      {/* Botão invisível para virar o card */}
      <button onClick={()=>setFlipped(f=>!f)}
        style={{ width:"100%", height:"80px", background:"transparent", border:"none", cursor:"pointer", flexShrink:0, WebkitTapHighlightColor:"transparent", outline:"none" }}/>

      {/* Navegação anterior / próximo */}
      <div style={{ display:"flex", gap:"8px", marginBottom:"12px" }}>
        <button onClick={goPrev}
          style={{ flex:1, padding:"18px 0", borderRadius:"18px", border:"none", cursor:"pointer",
            backgroundColor:theme.soft, color:theme.muted,
            fontSize:"22px", fontWeight:300, transition:"background 0.15s" }}>←</button>
        <button onClick={goNext}
          style={{ flex:1, padding:"18px 0", borderRadius:"18px", border:"none", cursor:"pointer",
            backgroundColor:theme.soft, color:theme.muted,
            fontSize:"22px", fontWeight:300, transition:"background 0.15s" }}>→</button>
      </div>


    </div>
  );
}

// ─── CustomCardModal — criar ou editar card do zero ──────────────────────────

const CAT_OPTIONS = ["verb","subst","adj","pron","adv","prep","conj","part","interj","other"];

function CustomCardModal({ theme, t, language, card, onSave, onDelete, onClose }) {
  const isEdit = !!card;
  const [greek,  setGreek]  = useState(card?.greek  ?? "");
  const [cat,    setCat]    = useState(card?.cat    ?? "subst");
  const [glosa,  setGlosa]  = useState(card?.glosses?.[language] ?? "");
  const [verse,  setVerse]  = useState(card?.verse  ?? "");
  const [ref_,   setRef_]   = useState(card?.reference ?? "");
  const [note,   setNote]   = useState(card?.note   ?? "");

  const canSave = greek.trim().length > 0 && glosa.trim().length > 0;

  const inputStyle = {
    width:"100%", background:"none", border:"1px solid "+theme.border, borderRadius:"12px",
    padding:"10px 14px", color:theme.text, fontSize:"1.0769em", outline:"none",
    fontFamily:"inherit", boxSizing:"border-box",
  };
  const labelStyle = {
    color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.18em",
    textTransform:"uppercase", marginBottom:"6px", display:"block",
  };

  function handleSave() {
    if (!canSave) return;
    const existing = card ?? {};
    const glosses = { ...(existing.glosses ?? {}), [language]: glosa.trim() };
    onSave({
      ...existing,
      greek: greek.trim(), cat, glosses,
      verse: verse.trim(), reference: ref_.trim(),
      note: note.trim(), custom: true,
    });
  }

  return (
    <div style={{ position:"fixed", inset:0, backgroundColor:"rgba(0,0,0,0.55)", zIndex:200, display:"flex", alignItems:"flex-start", justifyContent:"center", padding:"120px 20px 0" }}
      onClick={e=>{ if(e.target===e.currentTarget) onClose(); }}>
      <div style={{ backgroundColor:theme.card, borderRadius:"24px", padding:"24px 20px 32px", width:"100%", boxSizing:"border-box", maxHeight:"75vh", overflowY:"auto" }}>

        {/* Header */}
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"20px" }}>
          <div style={{ fontSize:"1.1538em", fontWeight:300, letterSpacing:"0.04em" }}>
            {isEdit
              ? ({pt:"Editar card", en:"Edit card", de:"Karte bearbeiten", fr:"Modifier", es:"Editar tarjeta"})[language]
              : ({pt:"Novo card", en:"New card", de:"Neue Karte", fr:"Nouvelle carte", es:"Nueva tarjeta"})[language]}
          </div>
          <button onClick={onClose} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.5385em", lineHeight:1 }}>×</button>
        </div>

        {/* Grego */}
        <label style={labelStyle}>
          {{pt:"Palavra grega", en:"Greek word", de:"Griechisches Wort", fr:"Mot grec", es:"Palabra griega"}[language]}
        </label>
        <AndroidInput style={{ ...inputStyle, fontSize:"1.6923em", fontWeight:300, marginBottom:"14px" }}
          value={greek} onChange={e=>setGreek(e.target.value)}
          placeholder="π.χ. λόγος" readOnly={isEdit}/>

        {/* Categoria */}
        <label style={labelStyle}>
          {{pt:"Categoria", en:"Category", de:"Kategorie", fr:"Catégorie", es:"Categoría"}[language]}
        </label>
        <div style={{ display:"flex", flexWrap:"wrap", gap:"6px", marginBottom:"14px" }}>
          {CAT_OPTIONS.map(c => (
            <button key={c} onClick={()=>setCat(c)}
              style={{ padding:"5px 12px", borderRadius:"20px", fontSize:"0.8462em", cursor:"pointer",
                border:"1px solid "+(cat===c?theme.accent:theme.border),
                color:cat===c?theme.accent:theme.muted, background:"none" }}>
              {c}
            </button>
          ))}
        </div>

        {/* Tradução */}
        <label style={labelStyle}>
          {t.editGlosa} ({language})
        </label>
        <AndroidInput style={{ ...inputStyle, marginBottom:"14px" }}
          value={glosa} onChange={e=>setGlosa(e.target.value)}
          placeholder="—"/>

        {/* Versículo */}
        <label style={labelStyle}>
          {{pt:"Versículo (opcional)", en:"Verse (optional)", de:"Vers (optional)", fr:"Verset (optionnel)", es:"Versículo (opcional)"}[language]}
        </label>
        <AndroidInput style={{ ...inputStyle, marginBottom:"8px" }}
          value={verse} onChange={e=>setVerse(e.target.value)}
          placeholder="—"/>
        <AndroidInput style={{ ...inputStyle, marginBottom:"14px", fontSize:"0.9231em" }}
          value={ref_} onChange={e=>setRef_(e.target.value)}
          placeholder={{pt:"Referência (ex: João 1:1)", en:"Reference (e.g. John 1:1)", de:"Referenz (z.B. Johannes 1:1)", fr:"Référence (ex: Jean 1:1)", es:"Referencia (ej: Juan 1:1)"}[language]}/>

        {/* Nota */}
        <label style={labelStyle}>{t.editNote}</label>
        <AndroidInput style={{ ...inputStyle, marginBottom:"20px" }}
          value={note} onChange={e=>setNote(e.target.value)}
          placeholder="—"/>

        {/* Botões */}
        <div style={{ display:"flex", gap:"8px" }}>
          {isEdit && onDelete && (
            <button onClick={onDelete}
              style={{ flex:1, background:"none", border:"1px solid #c0392b44", borderRadius:"14px",
                padding:"12px 0", color:"#c0392b", fontSize:"0.9231em", cursor:"pointer" }}>
              {{pt:"Excluir", en:"Delete", de:"Löschen", fr:"Supprimer", es:"Eliminar"}[language]}
            </button>
          )}
          <button onClick={handleSave} disabled={!canSave}
            style={{ flex:2, backgroundColor:canSave?theme.accent:"transparent",
              border:"1px solid "+(canSave?theme.accent:theme.border),
              borderRadius:"14px", padding:"12px 0",
              color:canSave?"#fff":theme.muted, fontSize:"1.0em", cursor:canSave?"pointer":"not-allowed" }}>
            {t.save}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── ListDetail ───────────────────────────────────────────────────────────────

function ListDetail({ theme, t, language, list, onBack, onUpdate, onSRS, onQuizResults, showVerses }) {
  // overrides: { [greek]: { glosa, note } | null }
  const overrides = list.overrides ?? {};
  function saveOverride(greek, ov) {
    const next = { ...overrides };
    if (ov === null) delete next[greek]; else next[greek] = ov;
    onUpdate({ ...list, overrides: next });
  }
  const [showPicker,     setShowPicker]     = useState(false);
  const [showQuiz,       setShowQuiz]       = useState(false);
  const [showFlashCards, setShowFlashCards] = useState(false);
  const [editWord,       setEditWord]       = useState(null);
  const [showCustomModal,setShowCustomModal]= useState(false);
  const [editCustomCard, setEditCustomCard] = useState(null);

  const [customCards, setCustomCards] = useState(() => {
    try { return JSON.parse(localStorage.getItem("koine_custom_cards") || "{}"); } catch { return {}; }
  });
  function persistCustom(next) {
    setCustomCards(next);
    localStorage.setItem("koine_custom_cards", JSON.stringify(next));
  }
  function saveCustomCard(card) {
    const next = { ...customCards, [card.greek]: card };
    persistCustom(next);
    if (!list.words.includes(card.greek)) onUpdate({ ...list, words: [...list.words, card.greek] });
    setShowCustomModal(false); setEditCustomCard(null);
  }
  function deleteCustomCard(greek) {
    const next = { ...customCards }; delete next[greek];
    persistCustom(next);
    onUpdate({ ...list, words: list.words.filter(g => g !== greek) });
    setEditCustomCard(null); setShowCustomModal(false);
  }

  const cards = list.words.map(g => ALL_DICTIONARY.find(c => c.greek === g) || customCards[g] ).filter(Boolean);

  function saveWords(words) { onUpdate({ ...list, words }); setShowPicker(false); }

  const needsTwo = (
    <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:"12px" }}>
      <div style={{ color:theme.muted, fontSize:"1.0em", textAlign:"center", padding:"0 24px" }}>
        {{ pt:"Adicione pelo menos 2 palavras.", en:"Add at least 2 words.", de:"Mindestens 2 Wörter.", fr:"Ajoutez au moins 2 mots.", es:"Agrega al menos 2 palabras." }[language]}
      </div>
      <button onClick={() => { setShowQuiz(false); setShowFlashCards(false); }}
        style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em" }}>← {t.back}</button>
    </div>
  );

  if (showFlashCards) {
    if (cards.length < 1) return needsTwo;
    return <ListFlashCards theme={theme} t={t} language={language} cards={cards} onClose={() => setShowFlashCards(false)} onSRS={onSRS} overrides={overrides} onSaveOverride={saveOverride} showVerses={showVerses}/>;
  }

  if (showQuiz) {
    if (cards.length < 2) return needsTwo;
    return <QuizScreen theme={theme} t={t} language={language} cards={cards} onClose={() => setShowQuiz(false)} onSRS={onSRS}
      onWrongWords={null}
      onQuizResults={onQuizResults} allCards={[...ALL_600,...Object.values(JSON.parse(localStorage.getItem("koine_custom_cards")||'{}'))]}/>;
  }

  return (
    <div style={{ flex:1, display:"flex", flexDirection:"column" }}>

      {/* Modais */}
      {(showCustomModal || editCustomCard) && (
        <CustomCardModal
          theme={theme} t={t} language={language}
          card={editCustomCard}
          onSave={saveCustomCard}
          onDelete={editCustomCard ? ()=>deleteCustomCard(editCustomCard.greek) : undefined}
          onClose={()=>{ setShowCustomModal(false); setEditCustomCard(null); }}
        />
      )}

      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"16px", flexShrink:0, paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
        <button onClick={onBack} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em" }}>← {t.back}</button>
        <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.24em", textTransform:"uppercase" }}>{list.name}</div>
        <div style={{ display:"flex", alignItems:"center", gap:"4px" }}>
          <button onClick={()=>{ setShowCustomModal(true); setEditCustomCard(null); }}
            style={{ color:theme.accent, background:"none", border:"none", cursor:"pointer", padding:"0 4px", display:"flex", alignItems:"center" }}
            title={{pt:"Criar card", en:"Create card", de:"Karte erstellen", fr:"Créer carte", es:"Crear tarjeta"}[language]}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"><path d="M4 20h4l10.5-10.5a2.121 2.121 0 0 0-3-3L5 17v3z"/><line x1="14.5" y1="6.5" x2="17.5" y2="9.5"/><line x1="19" y1="3" x2="19" y2="7"/><line x1="17" y1="5" x2="21" y2="5"/></svg>
          </button>
          <button onClick={() => setShowPicker(true)} style={{ color:theme.accent, background:"none", border:"none", cursor:"pointer", padding:"0 4px", display:"flex", alignItems:"center" }} aria-label={t.addWord}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button>
        </div>
      </div>

      {/* Botões Flashcards e Quiz separados */}
      <div style={{ display:"flex", gap:"8px", marginBottom:"14px", flexShrink:0 }}>
        <button onClick={() => setShowFlashCards(true)}
          style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"13px 0",
            color:cards.length>=1?theme.text:theme.muted, fontSize:"1.0em", cursor:cards.length>=1?"pointer":"not-allowed", letterSpacing:"0.04em" }}>
          {{ pt:"Flashcards", en:"Flashcards", de:"Flashcards", fr:"Flashcards", es:"Flashcards" }[language]}
        </button>
        <button onClick={() => setShowQuiz(true)}
          style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"13px 0",
            color:cards.length>=2?theme.text:theme.muted, fontSize:"1.0em", cursor:cards.length>=2?"pointer":"not-allowed", letterSpacing:"0.04em" }}>
          {t.quiz}
        </button>
      </div>
      <div style={{ flex:1, overflowY:"auto", paddingBottom:"12px" }}>
        {cards.length===0 ? (
          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", height:"100%", gap:"8px", paddingTop:"40px" }}>
            <div style={{ color:theme.muted, fontSize:"1.0em" }}>{t.emptyList}</div>
            <div style={{ color:theme.muted, fontSize:"0.8462em", opacity:0.6 }}>{t.tapToAdd}</div>
          </div>
        ) : (
          <>
          {editWord && (() => {
            const ec = cards.find(c=>c.greek===editWord);
            return ec ? (
              <WordEditModal
                theme={theme} t={t} language={language} card={ec}
                override={overrides[ec.greek]}
                onSave={(ov)=>{ saveOverride(ec.greek, ov); setEditWord(null); }}
                onRestore={()=>{ const cur=overrides[ec.greek]; if(cur){ const g={...cur.glosses}; delete g[language]; saveOverride(ec.greek, (Object.keys(g).length||cur.note)?{...cur,glosses:g}:null); } setEditWord(null); }}
                onClose={()=>setEditWord(null)}
              />
            ) : null;
          })()}
          <div style={{ display:"flex", flexDirection:"column", gap:"6px", fontSize:"13px" }}>
            {cards.map(card => {
              const ov = overrides[card.greek];
              const displayGlosa = ov?.glosses?.[language] ?? card.glosses[language];
              const isCustom = !!card.custom;
              return (
                <div key={card.greek} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"12px 16px", backgroundColor:theme.card, border:"1px solid "+(isCustom?theme.accent+"44":theme.border), borderRadius:"16px" }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", alignItems:"baseline", gap:"6px" }}>
                      <span style={{ fontSize:"22px", fontWeight:300, lineHeight:1.2 }}>{card.greek}</span>
                      {isCustom && <span style={{ fontSize:"9px", color:theme.accent, opacity:0.7 }}>✦</span>}
                    </div>
                    <div style={{ color:theme.muted, fontSize:"11px", fontStyle:"italic", marginTop:"2px" }}>{displayGlosa}</div>
                    {ov?.note && <div style={{ color:theme.muted, fontSize:"10px", marginTop:"2px", opacity:0.7 }}>{ov.note}</div>}
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:"4px", flexShrink:0 }}>
                    <button onClick={()=>{ if(isCustom){ setEditCustomCard(card); setShowCustomModal(true); } else setEditWord(card.greek); }}
                      style={{ color:ov?.glosses?.[language]?theme.accent:theme.muted, background:"none", border:"none", cursor:"pointer", padding:"6px", display:"flex", alignItems:"center" }}
                      title={t.editWord}>
                      <PencilIcon size={13} color={isCustom?theme.accent:ov?.glosses?.[language]?theme.accent:theme.muted}/>
                    </button>
                    <DotsMenu theme={theme} options={[{ label:t.remove, danger:true, action:()=>onUpdate({ ...list, words:list.words.filter(g=>g!==card.greek) }) }]}/>
                  </div>
                </div>
              );
            })}
          </div>
          </>
        )}
      </div>
      {showPicker && <WordPicker theme={theme} t={t} language={language} currentWords={list.words} onDone={saveWords} allCards={[...ALL_DICTIONARY,...Object.values(JSON.parse(localStorage.getItem("koine_custom_cards")||'{}'))]}/>}
    </div>
  );
}

// ─── SettingsTab ──────────────────────────────────────────────────────────────

function SettingsTab({ theme, t, language, onReset, onResetOverrides, hasOverrides,
                       onExport, onImport, importStatus, showVerses, onToggleVerses,
                       onImportClick, onBack, importSettersRef, fontSize=0, onFontSize }) {
  const [confirm,       setConfirm]       = useState(null);
  const [importPreview, setImportPreview] = useState(null);
  const [importSel,     setImportSel]     = useState({});

  useEffect(() => { if (importSettersRef) importSettersRef.current = { setImportPreview, setImportSel }; });

  function confirmImport() {
    if (!importPreview) return;
    onImport(importPreview, importSel);
    setImportPreview(null);
  }

  const GearSection = ({ title, children }) => (
    <div style={{ backgroundColor:theme.card, border:"1px solid "+theme.border, borderRadius:"24px", padding:"14px", flexShrink:0 }}>
      <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"8px" }}>{title}</div>
      <div style={{ display:"flex", flexDirection:"column", gap:"8px" }}>{children}</div>
    </div>
  );

  const Row = ({ label, desc, onClick, danger }) => (
    <button onClick={onClick}
      style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
        background:"none", border:"1px solid "+(danger?"#c0392b44":theme.border),
        borderRadius:"16px", padding:"13px 16px", cursor:"pointer", textAlign:"left", width:"100%" }}>
      <div>
        <div style={{ color:danger?"#c0392b":theme.text, fontSize:"1.0em" }}>{label}</div>
        {desc && <div style={{ color:theme.muted, fontSize:"0.7692em", marginTop:"3px" }}>{desc}</div>}
      </div>
      <div style={{ color:danger?"#c0392b":theme.muted, fontSize:"1.2308em", opacity:0.5 }}>›</div>
    </button>
  );

  const Pill = ({ checked, onToggle }) => (
    <div onClick={onToggle} style={{ width:"40px", height:"22px", borderRadius:"11px",
      backgroundColor:checked?theme.accent:theme.border, display:"flex", alignItems:"center",
      padding:"2px", flexShrink:0, cursor:"pointer", transition:"background 0.2s", marginLeft:"12px" }}>
      <div style={{ width:"18px", height:"18px", borderRadius:"50%", backgroundColor:"#fff",
        transform:checked?"translateX(18px)":"translateX(0)", transition:"transform 0.2s" }}/>
    </div>
  );

  const CheckCircle = ({ checked }) => (
    <div style={{ width:"18px", height:"18px", borderRadius:"50%",
      border:"1px solid "+(checked?theme.accent:theme.border),
      backgroundColor:checked?theme.accent:"transparent",
      display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
      {checked && <svg width="10" height="10" viewBox="0 0 12 12" fill="none"><polyline points="2,6 5,9 10,3" stroke={theme.bg} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>}
    </div>
  );

  const confirmLabels = {
    learning:  { title: ({pt:"Reiniciar progresso?", en:"Reset progress?", de:"Fortschritt zuruecksetzen?", fr:"Reinitialiser la progression?", es:"Reiniciar progreso?"})[language],
                 body:  ({pt:"Apaga sequência, SRS, resultados e palavras aprendidas. Suas listas ficam intactas.", en:"Erases streak, SRS, results and learned words. Your lists remain intact.", de:"Loescht Serie, SRS, Ergebnisse und gelernte Woerter. Listen bleiben erhalten.", fr:"Efface serie, SRS, resultats et mots appris. Listes non affectees.", es:"Borra racha, SRS, resultados y palabras aprendidas. Listas intactas."})[language] },
    all:       { title: ({pt:"Reiniciar tudo?", en:"Reset everything?", de:"Alles zuruecksetzen?", fr:"Tout reinitialiser?", es:"Reiniciar todo?"})[language],
                 body:  ({pt:"Apaga progresso, listas e cards customizados. O vocabulário base permanece.", en:"Erases progress, lists and custom cards. Base vocabulary remains.", de:"Loescht Fortschritt, Listen und eigene Karten. Grundvokabular bleibt.", fr:"Efface progression, listes et cartes. Vocabulaire de base conserve.", es:"Borra progreso, listas y tarjetas. El vocabulario base permanece."})[language] },
  };

  const previewLists = importPreview?.lists?.lists ?? [];
  const hasCustom    = importPreview?.customCards && Object.keys(importPreview.customCards).length > 0;
  const hasProgress  = !!(importPreview?.learnedCards || importPreview?.srsData);

  return (
    <div style={{ flex:1, minHeight:0, display:"flex", flexDirection:"column", gap:"8px", overflowY:"auto", paddingBottom:"16px" }}>

      {/* Cabeçalho */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", flexShrink:0, marginBottom:"4px" }}>
        <button onClick={onBack} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em", padding:0 }}>← {t.back}</button>
        <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.25em", textTransform:"uppercase" }}>{t.settings}</div>
        <div style={{ display:"flex", gap:"6px" }}>
          {[0,1,2].map(s => (
            <button key={s} onClick={()=>{ onFontSize(s); navigator.vibrate?.(30); }}
              style={{ width:"28px", height:"28px", borderRadius:"50%",
                background:"none", border:"1px solid "+(fontSize===s?theme.accent:theme.border),
                color:fontSize===s?theme.accent:theme.muted,
                cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
                fontSize: s===0?"10px":s===1?"13px":"16px", fontWeight:300, transition:"all 0.15s",
                padding:0, flexShrink:0 }}>
              A
            </button>
          ))}
        </div>
      </div>

      {/* Reset confirm */}
      {confirm && (
        <div style={{ position:"fixed", inset:0, backgroundColor:"rgba(0,0,0,0.55)", zIndex:200, display:"flex", alignItems:"flex-end" }}>
          <div style={{ backgroundColor:theme.card, borderRadius:"24px 24px 0 0", padding:"24px 20px 32px", width:"100%", boxSizing:"border-box", maxHeight:"92vh", overflowY:"auto" }}>
            <div style={{ fontSize:"1.2308em", fontWeight:300, marginBottom:"8px" }}>{confirmLabels[confirm].title}</div>
            <div style={{ color:theme.muted, fontSize:"0.9231em", marginBottom:"20px" }}>{confirmLabels[confirm].body}</div>
            <div style={{ display:"flex", gap:"8px" }}>
              <button onClick={()=>setConfirm(null)}
                style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"14px", padding:"12px 0", color:theme.muted, fontSize:"1.0em", cursor:"pointer" }}>
                {t.cancel}
              </button>
              <button onClick={()=>{ onReset(confirm); setConfirm(null); }}
                style={{ flex:1, background:"none", border:"1px solid #c0392b", borderRadius:"14px", padding:"12px 0", color:"#c0392b", fontSize:"1.0em", cursor:"pointer" }}>
                {t.reset}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Import preview */}
      {importPreview && (
        <div style={{ position:"fixed", inset:0, backgroundColor:"rgba(0,0,0,0.55)", zIndex:200, display:"flex", alignItems:"flex-end" }}>
          <div style={{ backgroundColor:theme.card, borderRadius:"24px 24px 0 0", padding:"24px 20px 32px", width:"100%", boxSizing:"border-box", maxHeight:"80vh", overflowY:"auto" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"18px" }}>
              <div style={{ fontSize:"1.1538em", fontWeight:300 }}>
                {({pt:"O que importar?", en:"What to import?", de:"Was importieren?", fr:"Que importer?", es:"Que importar?"})[language]}
              </div>
              <button onClick={()=>setImportPreview(null)} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.5385em" }}>x</button>
            </div>

            {previewLists.length > 0 && (
              <div style={{ marginBottom:"16px" }}>
                <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.18em", textTransform:"uppercase", marginBottom:"10px" }}>
                  {({pt:"Listas", en:"Lists", de:"Listen", fr:"Listes", es:"Listas"})[language]} ({previewLists.length})
                </div>
                <div style={{ display:"flex", flexDirection:"column", gap:"6px" }}>
                  {previewLists.map(l => {
                    const sel = importSel.lists?.has(l.id);
                    return (
                      <button key={l.id}
                        onClick={()=>setImportSel(s=>{ const ns=new Set(s.lists); ns.has(l.id)?ns.delete(l.id):ns.add(l.id); return {...s,lists:ns}; })}
                        style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
                          background:"none", border:"1px solid "+(sel?theme.accent:theme.border),
                          borderRadius:"14px", padding:"10px 14px", cursor:"pointer", textAlign:"left", width:"100%" }}>
                        <div>
                          <div style={{ color:theme.text, fontSize:"1.0em" }}>{l.name}</div>
                          <div style={{ color:theme.muted, fontSize:"0.7692em", marginTop:"2px" }}>
                            {l.words?.length ?? 0} {({pt:"palavras", en:"words", de:"Woerter", fr:"mots", es:"palabras"})[language]}
                          </div>
                        </div>
                        <CheckCircle checked={sel}/>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {hasProgress && (
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"10px", padding:"10px 14px", border:"1px solid "+theme.border, borderRadius:"14px" }}>
                <div>
                  <div style={{ color:theme.text, fontSize:"1.0em" }}>
                    {({pt:"Progresso e SRS", en:"Progress & SRS", de:"Fortschritt & SRS", fr:"Progression & SRS", es:"Progreso y SRS"})[language]}
                  </div>
                  <div style={{ color:theme.muted, fontSize:"0.7692em", marginTop:"2px" }}>
                    {importPreview.learnedCards?.length ?? 0} {({pt:"palavras aprendidas", en:"learned words", de:"gelernte Woerter", fr:"mots appris", es:"palabras aprendidas"})[language]}
                  </div>
                </div>
                <Pill checked={importSel.progress} onToggle={()=>setImportSel(s=>({...s,progress:!s.progress}))}/>
              </div>
            )}

            {hasCustom && (
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"16px", padding:"10px 14px", border:"1px solid "+theme.border, borderRadius:"14px" }}>
                <div>
                  <div style={{ color:theme.text, fontSize:"1.0em" }}>
                    {({pt:"Cards customizados", en:"Custom cards", de:"Eigene Karten", fr:"Cartes personnalisees", es:"Tarjetas personalizadas"})[language]}
                  </div>
                  <div style={{ color:theme.muted, fontSize:"0.7692em", marginTop:"2px" }}>
                    {Object.keys(importPreview.customCards).length} cards
                  </div>
                </div>
                <Pill checked={importSel.custom} onToggle={()=>setImportSel(s=>({...s,custom:!s.custom}))}/>
              </div>
            )}

            <div style={{ display:"flex", gap:"8px" }}>
              <button onClick={()=>setImportPreview(null)}
                style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"14px", padding:"12px 0", color:theme.muted, fontSize:"1.0em", cursor:"pointer" }}>
                {t.cancel}
              </button>
              <button onClick={confirmImport}
                style={{ flex:2, backgroundColor:theme.accent, border:"none", borderRadius:"14px", padding:"12px 0", color:"#fff", fontSize:"1.0em", cursor:"pointer" }}>
                {({pt:"Importar selecionados", en:"Import selected", de:"Importieren", fr:"Importer", es:"Importar seleccionados"})[language]}
              </button>
            </div>
          </div>
        </div>
      )}



      {/* Dados */}
      <GearSection title={({pt:"Dados", en:"Data", de:"Daten", fr:"Donnees", es:"Datos"})[language]}>
        <div
          style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
            border:"1px solid "+theme.border, borderRadius:"16px",
            padding:"13px 16px", width:"100%", boxSizing:"border-box" }}>
          <div>
            <div style={{ color:theme.text, fontSize:"1.0em" }}>{t.showVerses}</div>
            <div style={{ color:theme.muted, fontSize:"0.7692em", marginTop:"3px" }}>{t.showVersesDesc}</div>
          </div>
          <Pill checked={showVerses} onToggle={onToggleVerses}/>
        </div>
        <Row label={t.exportData} desc={t.exportDesc} onClick={onExport}/>
        <Row label={t.importData} desc={t.importDesc} onClick={onImportClick}/>
        {importStatus && (
          <div style={{ color:importStatus==="ok"?"#6BA86A":"#C0706A", fontSize:"0.8462em", textAlign:"center", paddingTop:"4px" }}>
            {importStatus==="ok" ? t.importSuccess : t.importError}
          </div>
        )}
      </GearSection>

      {/* Restaurar */}
      <GearSection title={({pt:"Restaurar", en:"Restore", de:"Wiederherstellen", fr:"Restaurer", es:"Restaurar"})[language]}>
        <Row label={t.resetLearning} desc={({pt:"Apaga sequência, SRS e resultados. Mantém suas listas.", en:"Erases streak, SRS and results. Keeps your lists.", de:"Loescht Serie, SRS und Ergebnisse. Listen bleiben.", fr:"Efface serie, SRS et resultats. Listes conservees.", es:"Borra racha, SRS y resultados. Listas se mantienen."})[language]} onClick={()=>setConfirm("learning")}/>
        <Row label={t.resetAll} desc={({pt:"Apaga progresso, listas e cards customizados", en:"Erases progress, lists and custom cards", de:"Loescht Fortschritt, Listen und eigene Karten", fr:"Efface progression, listes et cartes", es:"Borra progreso, listas y tarjetas personalizadas"})[language]} danger onClick={()=>setConfirm("all")}/>
      </GearSection>

    </div>
  );
}


// ─── ListsTab ─────────────────────────────────────────────────────────────────

function ListsTab({ theme, t, language, onSRS, onQuizResults, listsRef, showVerses }) {
  const [state, setState]           = useState(() => {
    const s = load("koine_lists_v3", { lists:[] });
    // Remove a lista especial de erradas herdada de versões anteriores
    return { ...s, lists: s.lists.filter(l => l.id !== "koine_wrong_quiz_list") };
  });

  // Expor se alguma lista tem overrides
  const hasOverrides = state.lists.some(l => l.overrides && Object.values(l.overrides).some(ov => ov && (Object.keys(ov.glosses||{}).length > 0 || ov.note)));

  // Resetar todos os overrides de todas as listas
  const resetAllOverrides = useCallback(() => {
    setState(s=>({ ...s, lists: s.lists.map(l=>({ ...l, overrides:{} })) }));
  }, []);

  // Resetar todas as listas
  const resetLists = useCallback(() => {
    setState({ lists:[] });
  }, []);
  const [listsView, setListsView]   = useState("home"); // "home" | "detail:id"
  const [showNewList, setShowNewList] = useState(false);
  const [renameTarget, setRenameTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);

  useEffect(() => { save("koine_lists_v3", state); }, [state]);
  useEffect(() => { if(listsRef) listsRef.current = { hasOverrides, resetAllOverrides, resetLists }; }, [hasOverrides, resetAllOverrides, resetLists, listsRef]);

  const createList = useCallback((name) => {
    setState(s=>({ ...s, lists:[...s.lists, { id:uid(), name, words:[] }] }));
    setShowNewList(false);
  }, []);

  const renameList = useCallback((id, name) => {
    setState(s=>({ ...s, lists:s.lists.map(l=>l.id===id?{ ...l, name }:l) }));
    setRenameTarget(null);
  }, []);

  const deleteList = useCallback((id) => {
    setState(s=>({ ...s, lists:s.lists.filter(l=>l.id!==id) }));
    setDeleteTarget(null);
    if (listsView==="detail:"+id) setListsView("home");
  }, [listsView]);

  const updateList = useCallback((updated) => {
    setState(s=>({ ...s, lists:s.lists.map(l=>l.id===updated.id?updated:l) }));
  }, []);

  // Detalhe de lista
  if (listsView.startsWith("detail:")) {
    const listId = listsView.slice(7);
    const list   = state.lists.find(l=>l.id===listId);
    if (!list) { setListsView("home"); return null; }
    return (
      <div style={{ flex:1, display:"flex", flexDirection:"column" }}>
        <ListDetail theme={theme} t={t} language={language} list={list} onBack={()=>setListsView("home")} onUpdate={updateList} onSRS={onSRS} onQuizResults={onQuizResults} showVerses={showVerses}/>
      </div>
    );
  }

  // Listagem principal
  return (
    <div style={{ flex:1, display:"flex", flexDirection:"column", position:"relative" }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"16px", flexShrink:0 }}>
        <div>
          <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.25em", textTransform:"uppercase" }}>Koine</div>
          <div style={{ color:theme.muted, fontSize:"0.9231em", marginTop:"2px" }}>{t.lists}</div>
        </div>
        <button onClick={()=>setShowNewList(true)} style={{ color:theme.accent, background:"none", border:"none", cursor:"pointer", fontSize:"2.0em", lineHeight:1, padding:"0 4px" }}>+</button>
      </div>

      <div style={{ flex:1, overflowY:"auto", paddingBottom:"12px" }}>
        {state.lists.length===0 ? (
          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", paddingTop:"40px", gap:"8px" }}>
            <div style={{ color:theme.muted, fontSize:"1.0em" }}>{t.noLists}</div>
            <div style={{ color:theme.muted, fontSize:"0.8462em", opacity:0.6 }}>{t.tapPlus}</div>
          </div>
        ) : (
          <div style={{ display:"flex", flexDirection:"column", gap:"6px", paddingTop:"2px" }}>
            {(() => {
              const qr = JSON.parse(localStorage.getItem("koine_quiz_results") || "{}");
              return state.lists.map(list => {
                const consolidated = list.words.filter(g => qr[g] && !qr[g].wrong && qr[g].time <= 6).length;
                const studied = list.words.filter(g => qr[g]).length;
                const pct = list.words.length > 0 ? Math.round((consolidated / list.words.length) * 100) : 0;
                return (
                  <div key={list.id} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"14px 16px",
                    backgroundColor:theme.card, border:"1px solid "+theme.border,
                    borderRadius:"18px", cursor:"pointer" }}
                    onClick={()=>setListsView("detail:"+list.id)}>
                    <div>
                      <div style={{ color:theme.muted, fontSize:"0.6923em", letterSpacing:"0.22em", textTransform:"uppercase", marginBottom:"4px" }}>
                        {list.words.length} {{ pt:"palavras", en:"words", de:"Wörter", fr:"mots", es:"palabras" }[language]}
                      </div>
                      <div style={{ fontSize:"1.3077em", fontWeight:300 }}>{list.name}</div>
                    </div>
                    <div style={{ display:"flex", alignItems:"center", gap:"12px" }}>
                      {studied > 0 && (
                        <div style={{ fontSize:"0.7692em", color: pct === 100 ? "#6BA86A" : pct >= 50 ? "#D4A853" : theme.muted, opacity:0.6 }}>
                          {consolidated}/{list.words.length}
                        </div>
                      )}
                      <DotsMenu theme={theme} options={[
                        { label:t.rename, action:()=>setRenameTarget(list.id) },
                        { label:t.delete, danger:true, action:()=>setDeleteTarget(list.id) },
                      ]}/>
                    </div>
                  </div>
                );
              });
            })()}
          </div>
        )}
      </div>

      {showNewList   && <NameModal theme={theme} t={t} initialValue="" onSave={createList} onCancel={()=>setShowNewList(false)}/>}
      {renameTarget  && <NameModal theme={theme} t={t} initialValue={state.lists.find(l=>l.id===renameTarget)?.name||""} onSave={name=>renameList(renameTarget,name)} onCancel={()=>setRenameTarget(null)}/>}
      {deleteTarget  && <DeleteConfirm theme={theme} t={t} onConfirm={()=>deleteList(deleteTarget)} onCancel={()=>setDeleteTarget(null)}/>}
    </div>
  );
}

function SplashScreen({ darkMode, onDone }) {
  const bg    = darkMode ? "#151515" : "#F5F2EA";
  const text  = darkMode ? "#ECE7E1" : "#222222";
  const muted = darkMode ? "#A29B90" : "#7D776C";
  const ring  = darkMode ? "#333333" : "#E7E2D8";
  const dot   = darkMode ? "#8EA3D1" : "#5B6C8F";

  useEffect(() => {
    const t = setTimeout(onDone, 2200);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div style={{
      position:"fixed", inset:0, zIndex:9999,
      background:bg, display:"flex", flexDirection:"column",
      alignItems:"center", justifyContent:"center", overflow:"hidden",
      animation:"koine-splash-out 400ms ease-in 1900ms forwards",
      pointerEvents:"none",
    }}>
      <style>{`
        @keyframes koine-ring {
          0%   { opacity:0; transform:scale(0.4); }
          30%  { opacity:1; }
          100% { opacity:0; transform:scale(1); }
        }
        @keyframes koine-fadein {
          from { opacity:0; transform:translateY(10px); }
          to   { opacity:1; transform:translateY(0); }
        }
        @keyframes koine-dot {
          0%,100% { opacity:0.3; transform:scale(0.9); }
          50%     { opacity:1;   transform:scale(1.1); }
        }
        @keyframes koine-splash-out {
          from { opacity:1; }
          to   { opacity:0; }
        }
      `}</style>

      {[0, 0.5, 1.0].map((delay, i) => (
        <div key={i} style={{
          position:"absolute", borderRadius:"50%",
          border:"1px solid "+ring,
          width: [160, 260, 370][i], height: [160, 260, 370][i],
          animation:`koine-ring 3s ease-out ${delay}s infinite`,
          opacity:0,
        }}/>
      ))}

      <div style={{
        position:"relative", zIndex:2, display:"flex",
        flexDirection:"column", alignItems:"center", gap:"6px",
        animation:"koine-fadein 1s ease forwards",
      }}>
        <div style={{
          fontFamily:"Georgia, serif", fontSize:"42px",
          fontWeight:300, color:text, letterSpacing:"0.02em", lineHeight:1,
        }}>Κοινή</div>
        <div style={{
          fontSize:"11px", letterSpacing:"0.18em",
          textTransform:"uppercase", color:muted, marginTop:"4px",
        }}>Grego do Novo Testamento</div>
        <div style={{ display:"flex", gap:"6px", marginTop:"28px" }}>
          {[0, 0.3, 0.6].map((delay, i) => (
            <div key={i} style={{
              width:"4px", height:"4px", borderRadius:"50%",
              background:dot, opacity:0.4,
              animation:`koine-dot 1.6s ease-in-out ${delay}s infinite`,
            }}/>
          ))}
        </div>
      </div>

      <div style={{
        position:"absolute", bottom:"calc(40px + env(safe-area-inset-bottom, 20px))", zIndex:2,
        fontSize:"10px", letterSpacing:"0.35em",
        textTransform:"uppercase", color:text, opacity:0.4,
      }}>Koine</div>
    </div>
  );
}

// ─── KoineApp (componente raiz) ───────────────────────────────────────────────

export default function KoineApp() {
  const allCards    = useAllCards();
  // Preferências
  const [language,  setLanguage]  = useState(() => load("koine_lang",  "pt"));
  const [darkMode,  setDarkMode]  = useState(() => load("koine_dark",  true));
  const [fontSize,  setFontSize]  = useState(() => load("koine_fontsize", 0)); // 0=normal, 1=+1, 2=+2
  const [showSplash, setShowSplash] = useState(true);

  useEffect(() => {
    import("@capacitor/status-bar").then(({ StatusBar }) => {
      StatusBar.hide().catch(()=>{});
    }).catch(()=>{});
  }, []);

  useEffect(() => {
    try {
      if (window.AndroidTheme) window.AndroidTheme.setTheme(darkMode);
    } catch(e) {}
  }, [darkMode]);



  // Estudo
  const [learnedCards, setLearnedCards] = useState(() => load("koine_learned", []));
  const [srsData,      setSrsData]      = useState(() => load("koine_srs",     {}));
  const [streak,       setStreak]       = useState(() => load("koine_streak",  0));

  // Navegação
  const [activeTab,      setActiveTab]      = useState("home");
  const [selectedLevel,  setSelectedLevel]  = useState(null);
  const [selectedStage,  setSelectedStage]  = useState(null);
  const [cardIndex,      setCardIndex]      = useState(0);
  const [cardStates,     setCardStates]     = useState({});

  const [reviewMode,     setReviewMode]     = useState(false); // revisão pendente via Progress
  const [vocabMode,      setVocabMode]      = useState(null);  // null | "flashcards" | "quiz"

  // Resultados do Quiz — { greek -> { time, wrong } } — acumulados por sessão
  const [quizResults,    setQuizResults]    = useState(() => {
    const raw = load("koine_quiz_results", {});
    const fixed = {};
    for (const [k, v] of Object.entries(raw)) {
      fixed[k] = { ...v, time: typeof v.time === "number" ? v.time : parseFloat(v.time) || 0 };
    }
    return fixed;
  });
  // Revisão por grupo vinda do ProgressTab — { mode: "flash"|"quiz", greeks: [...] }
  const [reviewGroup,    setReviewGroup]    = useState(null);

  // Ref para expor hasOverrides e resetAllOverrides do ListsTab
  const listsRef = useRef({ hasOverrides: false, resetAllOverrides: ()=>{}, resetLists: ()=>{} });
  const importFileRef    = useRef(null);
  const importSettersRef = useRef({ setImportPreview: ()=>{}, setImportSel: ()=>{} });

  function processFile(f) {
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target.result);
        if (!data.version) throw new Error("invalid");
        const listIds = data.lists?.lists ? data.lists.lists.map(l=>l.id) : [];
        importSettersRef.current.setImportSel({ lists: new Set(listIds), progress: !!(data.learnedCards||data.srsData||data.streak), custom: !!(data.customCards&&Object.keys(data.customCards).length) });
        importSettersRef.current.setImportPreview(data);
      } catch { setImportStatus("error"); setTimeout(()=>setImportStatus(null),3000); }
    };
    reader.readAsText(f);
  }

  function processFile(f) {
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target.result);
        if (!data.version) throw new Error("invalid");
        const listIds = data.lists?.lists ? data.lists.lists.map(l=>l.id) : [];
        importSettersRef.current.setImportSel({
          lists: new Set(listIds),
          progress: !!(data.learnedCards || data.srsData || data.streak),
          custom: !!(data.customCards && Object.keys(data.customCards).length),
        });
        importSettersRef.current.setImportPreview(data);
      } catch { setImportStatus("error"); setTimeout(()=>setImportStatus(null),3000); }
    };
    reader.readAsText(f);
  }

  // Export / Import
  const [importStatus, setImportStatus] = useState(() => {
    const flag = localStorage.getItem("koine_import_status");
    if (flag === "ok") { localStorage.removeItem("koine_import_status"); return "ok"; }
    return null;
  });
  useEffect(() => { if (importStatus === "ok") setTimeout(()=>setImportStatus(null), 3000); }, []); // null | 'ok' | 'error'
  const [showVerses,   setShowVerses]   = useState(() => load("koine_show_verses", true));

  const handleExport = useCallback(async () => {
    const data = {
      version: 1, learnedCards, srsData, streak, quizResults,
      lists: JSON.parse(localStorage.getItem("koine_lists_v3") || "{}"),
      customCards: JSON.parse(localStorage.getItem("koine_custom_cards") || "{}"),
    };
    const json = JSON.stringify(data, null, 2);

    try {
      const { Filesystem, Directory } = await import("@capacitor/filesystem");
      const { Share } = await import("@capacitor/share");
      const result = await Filesystem.writeFile({
        path: "koine_backup.json",
        data: json,
        directory: Directory.Cache,
        encoding: "utf8",
      });
      await Share.share({
        title: "koine_backup.json",
        text: "Backup do Koine",
        files: [result.uri],
        dialogTitle: "Salvar backup do Koine",
      });
      return;
    } catch (e) {
      const msg = e?.message || String(e);
      if (msg.toLowerCase().includes("cancel")) return;
    }

    // Fallback: data URI
    try {
      const uri = "data:application/json;charset=utf-8," + encodeURIComponent(json);
      const a = document.createElement("a");
      a.href = uri;
      a.download = "koine_backup.json";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } catch {}
  }, [learnedCards, srsData, streak, quizResults]);

  const handleImport = useCallback((data, sel) => {
    if (!data) { setImportStatus("error"); setTimeout(()=>setImportStatus(null),3000); return; }
    try {
      let needsReload = false;

      // Merge listas selecionadas
      if (sel?.lists?.size > 0 && data.lists?.lists) {
        const existing = JSON.parse(localStorage.getItem("koine_lists_v3") || '{"lists":[]}');
        const existingIds = new Set((existing.lists||[]).map(l=>l.id));
        const toAdd = data.lists.lists.filter(l => sel.lists.has(l.id));
        const merged = [...(existing.lists||[])];
        toAdd.forEach(l => {
          if (existingIds.has(l.id)) {
            merged.push({ ...l, id: l.id+"_"+Date.now(), name: l.name+" (2)" });
          } else {
            merged.push(l);
          }
        });
        localStorage.setItem("koine_lists_v3", JSON.stringify({ ...existing, lists: merged }));
        needsReload = true;
      }

      // Progresso
      if (sel?.progress) {
        if (data.learnedCards) setLearnedCards(data.learnedCards);
        if (data.srsData)      setSrsData(data.srsData);
        if (data.streak)       setStreak(data.streak);
        if (data.quizResults)  setQuizResults(data.quizResults);
      }

      // Cards customizados
      if (sel?.custom && data.customCards) {
        const existing = JSON.parse(localStorage.getItem("koine_custom_cards") || "{}");
        localStorage.setItem("koine_custom_cards", JSON.stringify({ ...existing, ...data.customCards }));
        needsReload = true;
      }

      // Se importou listas ou cards, recarrega para atualizar estado em memória
      if (needsReload) {
        localStorage.setItem("koine_import_status", "ok");
        window.location.reload();
        return;
      }

      setImportStatus("ok");
      setTimeout(()=>setImportStatus(null), 3000);
    } catch {
      setImportStatus("error");
      setTimeout(()=>setImportStatus(null), 3000);
    }
  }, []);

  // Persistência
  useEffect(() => { save("koine_lang",        language);    }, [language]);
  useEffect(() => { save("koine_dark",        darkMode);    }, [darkMode]);
  useEffect(() => { save("koine_fontsize",    fontSize);    }, [fontSize]);
  useEffect(() => { save("koine_learned",     learnedCards);}, [learnedCards]);
  useEffect(() => { save("koine_srs",         srsData);     }, [srsData]);
  useEffect(() => { save("koine_streak",      streak);      }, [streak]);
  useEffect(() => { save("koine_quiz_results",quizResults); }, [quizResults]);
  useEffect(() => { save("koine_show_verses", showVerses);  }, [showVerses]);

  // Streak
  useEffect(() => {
    const today     = new Date().toDateString();
    const lastVisit = localStorage.getItem("koine_last_visit");
    if (lastVisit !== today) {
      const yesterday = new Date(Date.now()-86400000).toDateString();
      setStreak(prev => lastVisit===yesterday ? prev+1 : 1);
      localStorage.setItem("koine_last_visit", today);
    }
  }, []);

  // SRS unificado — chamado tanto pelo QuizScreen do Vocabulário quanto pelo das Listas
  const updateSRS = useCallback((greek, rating) => {
    setSrsData(prev => ({ ...prev, [greek]: computeSRS(prev[greek], rating) }));
  }, []);

  // Salva resultados de tempo do quiz — merge: erro sobrescreve acerto, acerto não regride consolidada
  const handleQuizResults = useCallback((results) => {
    setQuizResults(prev => {
      const merged = { ...prev };
      for (const [greek, entry] of Object.entries(results)) {
        const old = merged[greek];
        // Se errou: sempre marca como wrong
        if (entry.wrong) { merged[greek] = entry; continue; }
        // Se acertou: só atualiza se não havia ou se melhora a categoria
        if (!old || old.wrong) { merged[greek] = entry; continue; }
        // Ambos acertos: mantém o menor tempo (melhor)
        if (entry.time < old.time) { merged[greek] = entry; }
      }
      return merged;
    });
  }, []);

  // Abre revisão por grupo vinda do ProgressTab
  const handleReviewGroup = useCallback((mode, greeks) => {
    if (!greeks.length) return;
    setReviewGroup({ mode, greeks });
  }, []);

  // Palavras para revisão hoje
  const dueCards = useMemo(() =>
    allCards.filter(c => {
      const entry = srsData[c.greek];
      if (!entry) return learnedCards.includes(c.greek);
      return Date.now() >= entry.nextReview;
    }),
  [srsData, learnedCards]);

  // Versículo do dia — circula apenas pelas 600 palavras fixas
  const dailyVerse = useMemo(() => {
    const dayIndex = Math.floor(Date.now()/86400000);
    return ALL_600[dayIndex % ALL_600.length];
  }, []);

  // Helpers de navegação
  const theme = darkMode ? DARK : LIGHT;
  const t     = UI[language];

  const stageSlice   = useMemo(() => {
    if (selectedLevel && selectedStage) return CARDS_BY_LEVEL[selectedLevel]?.[selectedStage] ?? [];
    if (selectedLevel && !selectedStage) return Object.values(CARDS_BY_LEVEL[selectedLevel] ?? {}).flat();
    return [];
  }, [selectedLevel, selectedStage]);
  const visibleCards = useMemo(() => stageSlice.filter(c=>!learnedCards.includes(c.greek)), [stageSlice, learnedCards]);
  const safeIndex    = visibleCards.length ? Math.min(cardIndex, visibleCards.length-1) : 0;
  const currentCard  = visibleCards[safeIndex] ?? null;
  const homeWord     = useMemo(() => {
    const dayIndex = Math.floor(Date.now()/86400000);
    const offset   = Math.floor(ALL_600.length / 2);
    return ALL_600[(dayIndex + offset) % ALL_600.length];
  }, []);

  const nextLanguage  = useCallback(() => { setLanguage(l=>LANGS[(LANGS.indexOf(l)+1)%LANGS.length]); navigator.vibrate?.(40); }, []);
  const toggleCard    = useCallback((id)   => setCardStates(p=>({ ...p, [id]:!p[id] })), []);
  const changeTab     = useCallback((tab)  => { setActiveTab(tab); setSelectedLevel(null); setSelectedStage(null); setReviewMode(false); setVocabMode(null); setReviewGroup(null); }, []);


  // Nav inferior
  const NAV = [
    { id:"home",       label:t.home,       icon:"Α" },
    { id:"lists",      label:t.lists,      icon:"Σ" },
    { id:"vocabulary", label:t.vocabulary, icon:<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"><line x1="12" y1="1" x2="12" y2="23"/><line x1="5" y1="4" x2="19" y2="4"/><line x1="3" y1="9" x2="21" y2="9"/></svg> },
    { id:"progress",   label:t.progress,   icon:"Ω" },
  ];

  // Revisão por grupo do ProgressTab (Flashcards ou Quiz)
  if (reviewGroup) {
    const groupCards = reviewGroup.greeks.map(g => allCards.find(c => c.greek === g)).filter(Boolean);
    if (reviewGroup.mode === "flash") {
      return (
        <div style={{ backgroundColor:theme.bg, color:theme.text }} className="min-h-screen w-full flex items-center justify-center">
          <div className="w-full h-[100dvh] flex flex-col relative" style={{ backgroundColor:theme.bg }}>
            <div className="px-5 pb-2 flex-1 flex flex-col overflow-y-auto" style={{ paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
              <ListFlashCards theme={theme} t={t} language={language} cards={groupCards}
                onClose={()=>setReviewGroup(null)} onSRS={updateSRS} showVerses={showVerses}/>
            </div>
          </div>
        </div>
      );
    }
    if (reviewGroup.mode === "quiz" && groupCards.length >= 2) {
      return (
        <div style={{ backgroundColor:theme.bg, color:theme.text }} className="min-h-screen w-full flex items-center justify-center">
          <div className="w-full h-[100dvh] flex flex-col relative" style={{ backgroundColor:theme.bg }}>
            <div className="px-5 pb-2 flex-1 flex flex-col overflow-y-auto" style={{ paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
              <QuizScreen theme={theme} t={t} language={language} cards={groupCards}
                onClose={()=>setReviewGroup(null)} onSRS={updateSRS} onWrongWords={null}
                onQuizResults={handleQuizResults} allCards={allCards}/>
            </div>
          </div>
        </div>
      );
    }
    // fallback: não há cards suficientes — volta silenciosamente
    return null;
  }

  // Revisão pendente (abre QuizScreen com dueCards)
  if (reviewMode && dueCards.length >= 2) {
    return (
      <div style={{ backgroundColor:theme.bg, color:theme.text }} className="min-h-screen w-full flex items-center justify-center">
        <div className="w-full h-[100dvh] flex flex-col relative" style={{ backgroundColor:theme.bg }}>
          <div className="px-5 pb-2 flex-1 flex flex-col overflow-y-auto" style={{ paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
            <QuizScreen theme={theme} t={t} language={language} cards={dueCards}
              onClose={()=>setReviewMode(false)} onSRS={updateSRS} allCards={allCards} onWrongWords={null}
              onQuizResults={handleQuizResults}/>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ backgroundColor:theme.bg, color:theme.text }} className="min-h-screen w-full flex items-center justify-center overflow-hidden transition-colors duration-500">
      {showSplash && <SplashScreen darkMode={darkMode} onDone={() => setShowSplash(false)} />}
      <style>{`@keyframes koine-fade{from{opacity:0}to{opacity:1}} *{-webkit-tap-highlight-color:transparent; user-select:none; -webkit-user-select:none;} input,textarea,[contenteditable]{user-select:text; -webkit-user-select:text;} *{scrollbar-width:none;-ms-overflow-style:none;-webkit-tap-highlight-color:transparent;} *::-webkit-scrollbar{display:none} :root{--sat:env(safe-area-inset-top,0px);--sab:env(safe-area-inset-bottom,0px)}`}</style>
      <div className="w-full h-[100dvh] flex flex-col relative" style={{ backgroundColor:theme.bg, fontSize: fontSize===1?"15px":fontSize===2?"17px":"13px" }}>
        {/* Conteúdo */}
        <div key={activeTab} className="px-5 pb-2 flex-1 flex flex-col overflow-y-auto" style={{ animation:"koine-fade 200ms ease-out", paddingTop:"calc(env(safe-area-inset-top, 44px) + 8px)" }}>
          {/* Vocabulário */}
          {activeTab==="vocabulary" && vocabMode==="flashcards" && stageSlice.length > 0 ? (
            <ListFlashCards theme={theme} t={t} language={language} cards={stageSlice} onClose={()=>setVocabMode(null)} onSRS={updateSRS} showVerses={showVerses}/>
          ) : activeTab==="vocabulary" && vocabMode==="quiz" && stageSlice.length >= 2 ? (
            <QuizScreen theme={theme} t={t} language={language} cards={stageSlice} onClose={()=>setVocabMode(null)} onSRS={updateSRS} onWrongWords={null} onQuizResults={handleQuizResults} allCards={allCards}/>
          ) : activeTab==="vocabulary" && selectedStage && !vocabMode ? (
            /* Tela de seleção de modo: Flashcards ou Quiz */
            <div style={{ display:"flex", flexDirection:"column", height:"100%" }}>
              <div className="flex items-center justify-between mb-6">
                <button onClick={()=>setSelectedStage(null)} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em" }}>← {t.back}</button>
                <div style={{ color:theme.muted, fontSize:"0.7692em", textTransform:"uppercase", letterSpacing:"0.24em" }}>{t.stage.toUpperCase()} {selectedStage}</div>
                <div style={{ width:36 }}/>
              </div>
              <div style={{ flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:"12px" }}>
                <div style={{ color:theme.muted, fontSize:"0.8462em", letterSpacing:"0.18em", textTransform:"uppercase", marginBottom:"8px" }}>
                  {stageSlice.length} {{ pt:"palavras", en:"words", de:"Wörter", fr:"mots", es:"palabras" }[language]}
                </div>
                <button onClick={()=>setVocabMode("flashcards")}
                  style={{ width:"100%", background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"16px 0",
                    color:theme.text, fontSize:"1.0769em", cursor:"pointer", letterSpacing:"0.04em" }}>
                  Flashcards
                </button>
                <button onClick={()=>{ if(stageSlice.length>=2) setVocabMode("quiz"); }}
                  style={{ width:"100%", background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"16px 0",
                    color:stageSlice.length>=2?theme.text:theme.muted, fontSize:"1.0769em",
                    cursor:stageSlice.length>=2?"pointer":"not-allowed", letterSpacing:"0.04em" }}>
                  {t.quiz}
                </button>
              </div>
            </div>
          ) : activeTab==="vocabulary" && selectedLevel && !selectedStage ? (
            /* Tela de etapas — com botões Flashcards+Quiz no topo do nível */
            <div className="flex-1 flex flex-col">
              <div className="flex items-center justify-between mb-4">
                <button onClick={()=>setSelectedLevel(null)} style={{ color:theme.muted, background:"none", border:"none", cursor:"pointer", fontSize:"1.0em" }}>← {t.back}</button>
                <div style={{ textAlign:"center" }}>
                  <div style={{ color:theme.muted, fontSize:"0.6923em", letterSpacing:"0.24em", textTransform:"uppercase" }}>
                    {{ pt:"NÍVEL", en:"LEVEL", de:"STUFE", fr:"NIVEAU", es:"NIVEL" }[language]} {selectedLevel}
                  </div>
                  <div style={{ color:theme.text, fontSize:"1.0em", fontWeight:300 }}>
                    {LEARNING_LEVELS.find(l=>l.id===selectedLevel)?.title[language]}
                  </div>
                </div>
                <div style={{ width:36 }}/>
              </div>
              {/* Botões de modo para o nível inteiro */}
              <div style={{ display:"flex", gap:"8px", marginBottom:"14px" }}>
                <button onClick={()=>{ if(stageSlice.length>=1) setVocabMode("flashcards"); }}
                  style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"13px 0",
                    color:stageSlice.length>=1?theme.text:theme.muted, fontSize:"1.0em",
                    cursor:stageSlice.length>=1?"pointer":"not-allowed", letterSpacing:"0.04em" }}>
                  Flashcards
                </button>
                <button onClick={()=>{ if(stageSlice.length>=2) setVocabMode("quiz"); }}
                  style={{ flex:1, background:"none", border:"1px solid "+theme.border, borderRadius:"16px", padding:"13px 0",
                    color:stageSlice.length>=2?theme.text:theme.muted, fontSize:"1.0em",
                    cursor:stageSlice.length>=2?"pointer":"not-allowed", letterSpacing:"0.04em" }}>
                  {t.quiz}
                </button>
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:"8px" }}>
                {LEVEL_STAGES[selectedLevel]?.map(stage => {
                  const words = CARDS_BY_LEVEL[selectedLevel]?.[stage.id] ?? [];
                  const available = words.length > 0;
                  const qr = JSON.parse(localStorage.getItem("koine_quiz_results") || "{}");
                  const studied = words.filter(c => qr[c.greek]).length;
                  const consolidated = words.filter(c => qr[c.greek] && !qr[c.greek].wrong && qr[c.greek].time <= 6).length;
                  const pct = words.length > 0 ? consolidated / words.length : 0;
                  return (
                    <button key={stage.id}
                      onClick={()=>{ if(available){ setSelectedStage(stage.id); setVocabMode(null); } }}
                      style={{ backgroundColor:theme.bg, border:"1px solid "+theme.border, borderRadius:"18px",
                        padding:"14px 16px", textAlign:"left", width:"100%",
                        cursor:available?"pointer":"default", opacity:available?1:0.45,
                        display:"flex", alignItems:"center", justifyContent:"space-between", gap:"12px" }}>
                      <span style={{ fontSize:"0.7692em", letterSpacing:"0.17em", color:theme.text, fontWeight:500, flex:1, lineHeight:1.4 }}>
                        {stage.theme ? stage.theme[language] : (t.stage+" "+stage.id)}
                        {!available && <span style={{ color:theme.muted, fontWeight:300, marginLeft:"8px" }}>
                          — {{ pt:"em breve", en:"coming soon", de:"demnächst", fr:"bientôt", es:"próximamente" }[language]}
                        </span>}
                      </span>
                      <div style={{ display:"flex", alignItems:"center", gap:"10px", flexShrink:0 }}>
                        {studied > 0 && (
                          <span style={{ fontSize:"0.7692em", color: pct === 1 ? "#6BA86A" : pct >= 0.5 ? "#D4A853" : theme.muted, opacity:0.6 }}>
                            {consolidated}/{words.length}
                          </span>
                        )}
                        <div style={{ width:"1px", height:"28px", background:theme.border }}/>
                        <span style={{ fontSize:"0.7692em", letterSpacing:"0.14em", color:theme.muted, whiteSpace:"nowrap" }}>
                          {t.stage.toUpperCase()} {stage.id}
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          ) : activeTab==="vocabulary" ? (
            /* Lista de níveis */
            <div className="flex-1 flex flex-col">
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"16px" }}>
                <div>
                  <div style={{ color:theme.muted, fontSize:"0.7692em", letterSpacing:"0.25em", textTransform:"uppercase" }}>Koine</div>
                  <div style={{ color:theme.muted, fontSize:"0.9231em", marginTop:"2px" }}>{t.vocabulary}</div>
                </div>
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:"8px" }}>
                {LEARNING_LEVELS.map(level => {
                  const totalWords = Object.values(CARDS_BY_LEVEL[level.id]||{}).flat().length;
                  const available  = totalWords > 0;
                  return (
                    <button key={level.id}
                      onClick={()=>{ if(available){ setSelectedLevel(level.id); setSelectedStage(null); setVocabMode(null); } }}
                      style={{ border:"1px solid "+theme.border, borderRadius:"20px", padding:"16px 18px",
                        textAlign:"left", background:"transparent", width:"100%",
                        cursor:available?"pointer":"default", opacity:available?1:0.45 }}>
                      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:"4px" }}>
                        <div style={{ color:theme.muted, fontSize:"0.6923em", letterSpacing:"0.24em", textTransform:"uppercase" }}>
                          {{ pt:"NÍVEL", en:"LEVEL", de:"STUFE", fr:"NIVEAU", es:"NIVEL" }[language]} {level.id}
                        </div>
                        {!available && (
                          <div style={{ color:theme.muted, fontSize:"0.6923em", letterSpacing:"0.12em", textTransform:"uppercase" }}>
                            {{ pt:"em breve", en:"coming soon", de:"demnächst", fr:"bientôt", es:"próximamente" }[language]}
                          </div>
                        )}
                      </div>
                      <div style={{ fontSize:"1.5385em", fontWeight:300, color:theme.text }}>{level.title[language]}</div>
                    </button>
                  );
                })}
              </div>
            </div>
          ) : activeTab==="home" ? (
            <HomeTab theme={theme} t={t} language={language} homeWord={homeWord} dailyVerse={dailyVerse}
              cardStates={cardStates} onToggle={toggleCard} onNextLanguage={nextLanguage}
              onToggleDark={()=>{ setDarkMode(d=>!d); navigator.vibrate?.(40); }} darkMode={darkMode}/>
          ) : activeTab==="lists" ? (
            <ListsTab theme={theme} t={t} language={language} onSRS={updateSRS} onQuizResults={handleQuizResults} listsRef={listsRef} showVerses={showVerses}/>
          ) : activeTab==="settings" ? (
            <SettingsTab theme={theme} t={t} language={language}
              onBack={()=>changeTab("progress")}
              fontSize={fontSize} onFontSize={setFontSize}
              onReset={(level)=>{
                if(level==="all") {
                  ["koine_learned","koine_srs","koine_streak","koine_quiz_results",
                   "koine_lists_v3","koine_custom_cards"].forEach(k => localStorage.removeItem(k));
                  window.location.reload();
                }
                else if(level==="learning") { setLearnedCards([]); setSrsData({}); setStreak(0); setQuizResults({}); }
              }}
              onResetOverrides={()=>listsRef.current.resetAllOverrides?.()}
              hasOverrides={listsRef.current.hasOverrides}
              onExport={handleExport}
              onImport={handleImport}
              onImportClick={()=>importFileRef.current?.click()}
              importSettersRef={importSettersRef}
              onImportClick={()=>importFileRef.current?.click()}
              importSettersRef={importSettersRef}
              importStatus={importStatus}
              showVerses={showVerses}
              onToggleVerses={()=>setShowVerses(v=>!v)}/>
          ) : activeTab==="progress" ? (
              <ProgressTab theme={theme} t={t} language={language} learnedCards={learnedCards}
                streak={streak} dueCount={dueCards.length}
                onStartReview={()=>setReviewMode(true)}
                quizResults={quizResults} onReviewGroup={handleReviewGroup}
                onOpenSettings={()=>changeTab("settings")} allCards={allCards}/>
          ) : null}
        </div>

        {/* Settings overlay */}


        <input ref={importFileRef} type="file" accept="*/*" style={{ display:"none" }}
          onChange={(e)=>{
            const f=e.target.files?.[0];
            if(f) processFile(f);
          }}
          onClick={(e)=>{
            // Polling fallback para Android WebView que não dispara onChange
            const el = e.target;
            const poll = setInterval(()=>{
              if(el.files?.[0]) {
                clearInterval(poll);
                processFile(el.files[0]);
                el.value="";
              }
            }, 300);
            setTimeout(()=>clearInterval(poll), 60000);
          }}/>
        <input ref={importFileRef} type="file" accept="*/*" style={{ display:"none" }}
          onChange={(e)=>{ const f=e.target.files?.[0]; if(f) processFile(f); }}
          onClick={(e)=>{ const el=e.target; const poll=setInterval(()=>{ if(el.files?.[0]){ clearInterval(poll); processFile(el.files[0]); el.value=""; }},300); setTimeout(()=>clearInterval(poll),60000); }}/>
        {/* Nav inferior */}
        <nav style={{ borderTop:"1px solid "+theme.border, backgroundColor:theme.bg, flexShrink:0, paddingBottom:"env(safe-area-inset-bottom, 0px)" }} className="flex">
          {NAV.map(({ id, label, icon }) => (
            <button key={id} onClick={()=>{ navigator.vibrate?.(40); changeTab(id); }}
              style={{ color: activeTab===id ? theme.accent : theme.muted, backgroundColor:"transparent", border:"none", cursor:"pointer" }}
              className="flex-1 flex flex-col items-center gap-0.5 py-3">
              {typeof icon === "string"
                ? <span style={{ fontSize:"1.9231em", fontWeight:300, lineHeight:1, ...(id==="vocabulary"?{ filter:"grayscale(100%)" }:{}) }}>{icon}</span>
                : <span style={{ display:"flex", alignItems:"center", justifyContent:"center", width:"24px", height:"24px" }}>{icon}</span>
              }
              <span className="text-[10px]">{label}</span>
            </button>
          ))}
        </nav>
      </div>
    </div>
  );
}
